-- ============================================================
-- Anchor Point Business Setup & Travel — Complete MySQL Schema & Seed Data
-- Includes: 5 Tour Categories, 62 Tours & Attractions,
--           5 Business Setup Categories, 31 Corporate Services,
--           6 SEO Blog Articles, Site Settings & Admin Account.
-- ============================================================
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

DROP TABLE IF EXISTS `tour_categories`;
CREATE TABLE `tour_categories` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `name` VARCHAR(150) NOT NULL,
  `section_title` VARCHAR(190),
  `slug` VARCHAR(150) UNIQUE NOT NULL,
  `description` TEXT,
  `cta_text` TEXT,
  `seo_keywords` TEXT,
  `icon` VARCHAR(60) DEFAULT 'compass',
  `image` VARCHAR(255),
  `sort_order` INT DEFAULT 0,
  `seo_title` VARCHAR(255),
  `seo_desc` TEXT,
  `is_active` TINYINT(1) DEFAULT 1,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `tours`;
CREATE TABLE `tours` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `category_id` INT NOT NULL,
  `title` VARCHAR(190) NOT NULL,
  `slug` VARCHAR(190) UNIQUE NOT NULL,
  `badge` VARCHAR(80),
  `short_desc` TEXT,
  `long_desc` LONGTEXT,
  `duration` VARCHAR(120),
  `pickup_line` VARCHAR(190),
  `has_pickup` TINYINT(1) DEFAULT 1,
  `price_aed` DECIMAL(10,2) NOT NULL DEFAULT 0,
  `child_price_aed` DECIMAL(10,2) DEFAULT 0,
  `original_price_aed` DECIMAL(10,2) NULL,
  `age_policy` VARCHAR(255),
  `rating` DECIMAL(3,1) DEFAULT 4.9,
  `reviews_count` INT DEFAULT 120,
  `featured_image` VARCHAR(255),
  `gallery_json` LONGTEXT,
  `itinerary_json` LONGTEXT,
  `inclusions_json` LONGTEXT,
  `exclusions_json` LONGTEXT,
  `details_json` LONGTEXT,
  `pickup_details` TEXT,
  `availability` VARCHAR(120) DEFAULT 'Daily',
  `faq_json` LONGTEXT,
  `is_featured` TINYINT(1) DEFAULT 0,
  `is_combo` TINYINT(1) DEFAULT 0,
  `sort_order` INT DEFAULT 0,
  `is_active` TINYINT(1) DEFAULT 1,
  `seo_title` VARCHAR(255),
  `seo_desc` TEXT,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  INDEX `idx_cat_sort` (`category_id`, `sort_order`),
  INDEX `idx_slug` (`slug`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `service_categories`;
CREATE TABLE `service_categories` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `name` VARCHAR(150) NOT NULL,
  `slug` VARCHAR(150) UNIQUE NOT NULL,
  `description` TEXT,
  `icon` VARCHAR(60) DEFAULT 'briefcase',
  `sort_order` INT DEFAULT 0,
  `is_active` TINYINT(1) DEFAULT 1,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `services`;
CREATE TABLE `services` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `category_id` INT NOT NULL,
  `title` VARCHAR(190) NOT NULL,
  `slug` VARCHAR(190) UNIQUE NOT NULL,
  `badge` VARCHAR(80),
  `short_desc` TEXT,
  `content` LONGTEXT,
  `featured_image` VARCHAR(255),
  `price_starting_aed` DECIMAL(10,2) DEFAULT 0,
  `timeline` VARCHAR(120) DEFAULT '3-5 business days',
  `deliverables_json` LONGTEXT,
  `requirements_json` LONGTEXT,
  `faq_json` LONGTEXT,
  `sort_order` INT DEFAULT 0,
  `is_featured` TINYINT(1) DEFAULT 0,
  `is_active` TINYINT(1) DEFAULT 1,
  `seo_title` VARCHAR(255),
  `seo_desc` TEXT,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  INDEX `idx_serv_cat` (`category_id`),
  INDEX `idx_serv_slug` (`slug`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `blog_posts`;
CREATE TABLE `blog_posts` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `title` VARCHAR(255) NOT NULL,
  `slug` VARCHAR(190) UNIQUE NOT NULL,
  `category` VARCHAR(100) DEFAULT 'Guides',
  `excerpt` TEXT,
  `content` LONGTEXT,
  `featured_image` VARCHAR(255),
  `author` VARCHAR(120) DEFAULT 'Anchor Point Corporate Desk',
  `read_time` VARCHAR(40) DEFAULT '5 min read',
  `views` INT DEFAULT 350,
  `seo_title` VARCHAR(255),
  `seo_desc` TEXT,
  `seo_keywords` VARCHAR(255),
  `is_published` TINYINT(1) DEFAULT 1,
  `published_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  INDEX `idx_blog_slug` (`slug`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `tour_bookings`;
CREATE TABLE `tour_bookings` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `booking_ref` VARCHAR(64),
  `tour_id` INT NULL,
  `category_name` VARCHAR(150),
  `tour_title` VARCHAR(255),
  `customer_name` VARCHAR(190) NOT NULL,
  `customer_email` VARCHAR(190) NOT NULL,
  `country_code` VARCHAR(16) DEFAULT '+971',
  `customer_phone` VARCHAR(64) NOT NULL,
  `booking_date` VARCHAR(40) NOT NULL,
  `preferred_time` VARCHAR(120),
  `adults_count` INT DEFAULT 1,
  `children_count` INT DEFAULT 0,
  `children_ages` VARCHAR(190),
  `guests_count` INT DEFAULT 1,
  `pickup_location` VARCHAR(255),
  `nationality` VARCHAR(120),
  `special_requests` TEXT,
  `consent_given` TINYINT(1) DEFAULT 1,
  `source_page` VARCHAR(255),
  `utm_source` VARCHAR(120),
  `utm_medium` VARCHAR(120),
  `utm_campaign` VARCHAR(120),
  `utm_term` VARCHAR(120),
  `utm_content` VARCHAR(120),
  `total_price_aed` DECIMAL(10,2) DEFAULT 0,
  `status` VARCHAR(40) DEFAULT 'New',
  `email_sent` TINYINT(1) DEFAULT 0,
  `ip` VARCHAR(64),
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `leads`;
CREATE TABLE `leads` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `name` VARCHAR(190) NOT NULL,
  `phone` VARCHAR(64) NOT NULL,
  `email` VARCHAR(190),
  `service_id` INT NULL,
  `service_type` VARCHAR(120),
  `message` TEXT,
  `source_page` VARCHAR(255),
  `utm_source` VARCHAR(120),
  `utm_medium` VARCHAR(120),
  `utm_campaign` VARCHAR(120),
  `utm_term` VARCHAR(120),
  `utm_content` VARCHAR(120),
  `ip` VARCHAR(64),
  `user_agent` VARCHAR(255),
  `status` VARCHAR(40) DEFAULT 'New',
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `settings`;
CREATE TABLE `settings` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `setting_key` VARCHAR(120) UNIQUE,
  `setting_value` TEXT,
  `updated_at` DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `users`;
CREATE TABLE `users` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `name` VARCHAR(120),
  `email` VARCHAR(190) UNIQUE,
  `password_hash` VARCHAR(255),
  `role` VARCHAR(40) DEFAULT 'editor',
  `is_active` TINYINT(1) DEFAULT 1,
  `last_login` DATETIME NULL,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `login_attempts`;
CREATE TABLE `login_attempts` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `ip` VARCHAR(64),
  `attempted_at` DATETIME
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `activity_log`;
CREATE TABLE `activity_log` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `user_id` INT NULL,
  `action` VARCHAR(190),
  `entity_type` VARCHAR(80),
  `entity_id` INT DEFAULT 0,
  `details` TEXT,
  `ip` VARCHAR(64),
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Dumping data for table `tour_categories` (5 rows)
INSERT INTO `tour_categories` (`id`, `name`, `slug`, `description`, `icon`, `image`, `sort_order`, `seo_title`, `seo_desc`, `is_active`, `created_at`, `section_title`, `cta_text`, `seo_keywords`) VALUES (1, 'Desert Safari', 'desert-safari', 'Ride the golden dunes of Dubai and Abu Dhabi, then relax under the stars with a barbecue dinner and live shows. Pick up from your hotel is included on most tours.', 'sun', NULL, 1, 'Desert Safari Dubai & Abu Dhabi | Morning, Evening & VIP Tours', 'Book Dubai & Abu Dhabi desert safari tours with 4x4 hotel pick-up, dune bashing, camel rides, quad bikes, and live BBQ dinner shows. Instant WhatsApp confirmation.', 1, '2026-11-02 09:52:01', 'Desert Safari Adventures', 'Not sure which safari suits you? Chat with us on WhatsApp and we will help you choose.', 'desert safari Dubai, evening desert safari, overnight desert safari, quad bike Dubai, VIP desert safari');
INSERT INTO `tour_categories` (`id`, `name`, `slug`, `description`, `icon`, `image`, `sort_order`, `seo_title`, `seo_desc`, `is_active`, `created_at`, `section_title`, `cta_text`, `seo_keywords`) VALUES (2, 'City Tours', 'city-tours', 'See the best of Dubai, Abu Dhabi and Sharjah with a local guide, from modern skylines to old souks and grand mosques.', 'landmark', NULL, 2, 'UAE City Tours | Dubai, Abu Dhabi & Sharjah Sightseeing', 'Explore Dubai, Abu Dhabi, and Sharjah with licensed local guides and hotel pick-up. Half-day, full-day, Sheikh Zayed Mosque, and private chauffeur tours.', 1, '2026-11-02 09:52:01', 'UAE City Tours', 'Want a custom route? Tell us your hotel and dates on WhatsApp.', 'Dubai city tour, Abu Dhabi tour from Dubai, Sheikh Zayed Mosque tour, private tour Dubai');
INSERT INTO `tour_categories` (`id`, `name`, `slug`, `description`, `icon`, `image`, `sort_order`, `seo_title`, `seo_desc`, `is_active`, `created_at`, `section_title`, `cta_text`, `seo_keywords`) VALUES (3, 'Cruise Dinner', 'cruise-dinner', 'Dine on the water with views of the Dubai skyline lit up at night. Choose a traditional dhow or a modern glass-top boat.', 'ship', NULL, 3, 'Dhow Cruise & Yacht Dinner Dubai | Marina & Creek Cruises', 'Enjoy evening dhow cruise dinners in Dubai Marina and Dubai Creek or luxury yacht dining with buffet menus, live entertainment, and skyline views.', 1, '2026-11-02 09:52:01', 'Cruise Dinner Experiences', 'Planning a birthday or proposal? Message us on WhatsApp to add decorations and a cake.', 'dhow cruise dinner Dubai, Marina dinner cruise, Creek dinner cruise, yacht dinner Dubai');
INSERT INTO `tour_categories` (`id`, `name`, `slug`, `description`, `icon`, `image`, `sort_order`, `seo_title`, `seo_desc`, `is_active`, `created_at`, `section_title`, `cta_text`, `seo_keywords`) VALUES (4, 'Watersports', 'watersports', 'Jet ski, flyboard, parasailing and more along the Dubai coastline. Trained instructors and life jackets are provided for every activity.', 'waves', NULL, 4, 'Dubai Watersports | Jet Ski, Parasailing, Flyboarding & Fishing', 'Book thrilling Dubai watersports along Palm Jumeirah and Burj Al Arab: jet ski rides, parasailing, flyboarding, banana boat, scuba diving, and deep sea fishing.', 1, '2026-11-02 09:52:01', 'Watersports and Sea Adventures', 'Booking for a group? Ask us on WhatsApp for combo prices.', 'jet ski Dubai, parasailing Dubai, flyboard Dubai, Dubai watersports packages');
INSERT INTO `tour_categories` (`id`, `name`, `slug`, `description`, `icon`, `image`, `sort_order`, `seo_title`, `seo_desc`, `is_active`, `created_at`, `section_title`, `cta_text`, `seo_keywords`) VALUES (5, 'Tickets & Attractions', 'tickets-attractions', 'Skip the queue with official e-tickets for the UAE\'s top attractions: observation decks, theme parks, water parks, aquariums, museums, gardens, indoor adventure and money-saving combo passes, all with instant WhatsApp confirmation.', 'ticket', NULL, 5, 'UAE Attraction Tickets | Theme Parks, Burj Khalifa, Water Parks & More', 'Book Dubai and Abu Dhabi attraction tickets online: Burj Khalifa, theme parks, water parks, aquariums, museums, Global Village and combo passes with instant e-ticket confirmation.', 1, '2026-11-02 09:52:01', 'Tickets and Attractions', 'Want combo tickets or hotel transfers included? Ask us on WhatsApp.', 'Dubai attraction tickets, Burj Khalifa tickets, theme park tickets Dubai, Ferrari World tickets, Aquaventure tickets, Abu Dhabi attraction tickets, multi-park pass UAE');

-- Dumping data for table `tours` (62 rows)
INSERT INTO `tours` (`id`, `category_id`, `title`, `slug`, `badge`, `short_desc`, `long_desc`, `duration`, `price_aed`, `original_price_aed`, `rating`, `reviews_count`, `featured_image`, `gallery_json`, `itinerary_json`, `inclusions_json`, `exclusions_json`, `pickup_details`, `availability`, `faq_json`, `is_featured`, `is_combo`, `sort_order`, `is_active`, `seo_title`, `seo_desc`, `created_at`, `updated_at`, `pickup_line`, `has_pickup`, `child_price_aed`, `age_policy`, `details_json`) VALUES (1, 1, 'Morning Desert Safari', 'morning-desert-safari', '', 'Dune bashing, camel ride and sandboarding in cooler morning light', 'Beat the midday heat on our Morning Desert Safari across the Lahbab red dunes. After 4x4 pick-up from your hotel, your licensed safari marshal takes you across sweeping golden ridges followed by sandboarding and a traditional camel ride before returning you to the city before lunch.', '4 hours', 160.0, NULL, 4.9, 102, '/uploads/activities/morning-desert-safari-cover.webp', '["/uploads/activities/morning-desert-safari-cover.webp","/uploads/activities/gallery-desert-1.webp","/uploads/activities/gallery-desert-2.webp","/uploads/activities/gallery-desert-3.webp","/uploads/activities/gallery-desert-4.webp","/uploads/activities/gallery-desert-5.webp","/uploads/activities/gallery-desert-6.webp"]', '[]', '["4x4 Land Cruiser hotel pick-up and drop-off","35–45 mins red dune bashing with licensed desert driver","Short camel ride & desert sandboarding","Bottled water, soft drinks & Arabic coffee"]', '["Quad bike or dune buggy (available as add-on)","Professional souvenir photography","Gratuities / tips"]', 'Daily pick-up between 07:30 AM – 08:00 AM; return by 11:30 AM – 12:00 PM. Pick-up available across Dubai, Sharjah, and Abu Dhabi hotels (Abu Dhabi private supplement applies).', 'Daily', '[{"q":"How do I confirm my booking for Morning Desert Safari?","a":"Click \'Book on WhatsApp\' or submit the enquiry form below. Our UAE team replies within minutes on WhatsApp (+971 52 537 6838) with instant confirmation."},{"q":"Is hotel pick-up available?","a":"Hotel pick-up is included on most safari and sightseeing tours, and can be added to any cruise, watersport, or attraction ticket on WhatsApp."},{"q":"What is the cancellation policy?","a":"Free cancellation or date change up to 24 hours before pick-up time."}]', 1, 0, 1, 1, 'Morning Desert Safari | Book Online & WhatsApp — Anchor Point UAE', 'Dune bashing, camel ride and sandboarding in cooler morning light. Duration: 4 hours. From AED 160 per person. Instant confirmation on WhatsApp.', '2026-11-02 09:52:01', '2026-11-02 09:52:01', '4 hours, hotel pick-up', 1, 130.0, 'Adults 12+ yrs | Children 3–11 yrs (Under 3 joins private car only)', '{"overview":"Beat the midday heat on our Morning Desert Safari across the Lahbab red dunes. After 4x4 pick-up from your hotel, your licensed safari marshal takes you across sweeping golden ridges followed by sandboarding and a traditional camel ride before returning you to the city before lunch.","timings_pickup":"Daily pick-up between 07:30 AM – 08:00 AM; return by 11:30 AM – 12:00 PM. Pick-up available across Dubai, Sharjah, and Abu Dhabi hotels (Abu Dhabi private supplement applies).","important_notes":"Not recommended for pregnant guests, infants under 3 years, or guests with serious back, neck, or heart conditions. Wear light, breathable clothing and sunglasses.","cancellation":"Free cancellation or date change up to 24 hours before pick-up time.","reviews":[{"author":"Hannah W. (UK)","rating":5,"comment":"Cool morning air, zero crowds on the red dunes, and our driver Tariq took brilliant family photos."},{"author":"Marco R. (Italy)","rating":5,"comment":"Picked up right on time from Dubai Marina. Sandboarding down the high dunes was unforgettable."}]}');
INSERT INTO `tours` (`id`, `category_id`, `title`, `slug`, `badge`, `short_desc`, `long_desc`, `duration`, `price_aed`, `original_price_aed`, `rating`, `reviews_count`, `featured_image`, `gallery_json`, `itinerary_json`, `inclusions_json`, `exclusions_json`, `pickup_details`, `availability`, `faq_json`, `is_featured`, `is_combo`, `sort_order`, `is_active`, `seo_title`, `seo_desc`, `created_at`, `updated_at`, `pickup_line`, `has_pickup`, `child_price_aed`, `age_policy`, `details_json`) VALUES (2, 1, 'Evening Desert Safari with BBQ Dinner', 'evening-desert-safari-with-bbq-dinner', '', 'Dune bashing, sunset photo stop, camel ride, henna, live shows and dinner', 'Our signature UAE desert experience combines thrilling 4x4 dune bashing over golden dunes, a panoramic sunset stop, and an atmospheric Bedouin camp evening featuring henna art, camel rides, live cultural performances, and a generous international & Arabic BBQ buffet under the stars.', '6 hours', 150.0, NULL, 4.9, 109, '/uploads/activities/evening-desert-safari-with-bbq-dinner-cover.webp', '["/uploads/activities/evening-desert-safari-with-bbq-dinner-cover.webp","/uploads/activities/gallery-desert-1.webp","/uploads/activities/gallery-desert-2.webp","/uploads/activities/gallery-desert-3.webp","/uploads/activities/gallery-desert-4.webp","/uploads/activities/gallery-desert-5.webp","/uploads/activities/gallery-desert-6.webp"]', '[]', '["4x4 hotel pick-up and drop-off","Red dune bashing & desert sunset photo stop","Camel ride, sandboarding & henna painting","Open-buffet BBQ dinner (veg & non-veg) with unlimited water, tea & soft drinks","Live Tanoura dance, Khaliji dance & fire show"]', '["Quad bike ride (optional camp add-on)","Falcon souvenir photos & VIP table waiter service","Personal tips"]', 'Daily pick-up between 02:30 PM – 03:15 PM; drop-off around 09:00 PM – 09:30 PM. Door-to-door 4x4 pick-up from Dubai, Sharjah, and Ajman hotels; Abu Dhabi pick-up available on request.', 'Daily', '[{"q":"How do I confirm my booking for Evening Desert Safari with BBQ Dinner?","a":"Click \'Book on WhatsApp\' or submit the enquiry form below. Our UAE team replies within minutes on WhatsApp (+971 52 537 6838) with instant confirmation."},{"q":"Is hotel pick-up available?","a":"Hotel pick-up is included on most safari and sightseeing tours, and can be added to any cruise, watersport, or attraction ticket on WhatsApp."},{"q":"What is the cancellation policy?","a":"Free cancellation up to 24 hours prior to departure with full refund."}]', 1, 0, 2, 1, 'Evening Desert Safari with BBQ Dinner | Book Online & WhatsApp — Anchor Point UAE', 'Dune bashing, sunset photo stop, camel ride, henna, live shows and dinner. Duration: 6 hours. From AED 150 per person. Instant confirmation on WhatsApp.', '2026-11-02 09:52:01', '2026-11-02 09:52:01', '6 hours, hotel pick-up', 1, 120.0, 'Adults 12+ yrs | Children 3–11 yrs | Infants under 3 free (private car required for dune drive)', '{"overview":"Our signature UAE desert experience combines thrilling 4x4 dune bashing over golden dunes, a panoramic sunset stop, and an atmospheric Bedouin camp evening featuring henna art, camel rides, live cultural performances, and a generous international & Arabic BBQ buffet under the stars.","timings_pickup":"Daily pick-up between 02:30 PM – 03:15 PM; drop-off around 09:00 PM – 09:30 PM. Door-to-door 4x4 pick-up from Dubai, Sharjah, and Ajman hotels; Abu Dhabi pick-up available on request.","important_notes":"Dune bashing is not recommended for pregnant guests, infants under 3, or people with back or heart problems (direct camp transfer can be arranged on request).","cancellation":"Free cancellation up to 24 hours prior to departure with full refund.","reviews":[{"author":"Priya S. (India)","rating":5,"comment":"Best evening in Dubai! Great veg and grilled BBQ options and the fire show was spectacular."},{"author":"Daniel K. (Germany)","rating":5,"comment":"Superb organization from WhatsApp booking to hotel drop-off. Sunset on the dunes was magical."}]}');
INSERT INTO `tours` (`id`, `category_id`, `title`, `slug`, `badge`, `short_desc`, `long_desc`, `duration`, `price_aed`, `original_price_aed`, `rating`, `reviews_count`, `featured_image`, `gallery_json`, `itinerary_json`, `inclusions_json`, `exclusions_json`, `pickup_details`, `availability`, `faq_json`, `is_featured`, `is_combo`, `sort_order`, `is_active`, `seo_title`, `seo_desc`, `created_at`, `updated_at`, `pickup_line`, `has_pickup`, `child_price_aed`, `age_policy`, `details_json`) VALUES (3, 1, 'Overnight Desert Safari', 'overnight-desert-safari', '', 'Evening safari, overnight desert camp stay under the stars & sunrise breakfast', 'Experience the quiet magic of the Arabian desert after all evening visitors depart. Enjoy the full Evening Desert Safari & BBQ Dinner, sleep comfortably in a traditional desert tent beneath a star-filled sky, and wake to golden sunrise views with freshly prepared breakfast.', '18 hours', 380.0, NULL, 4.9, 116, '/uploads/activities/overnight-desert-safari-cover.webp', '["/uploads/activities/overnight-desert-safari-cover.webp","/uploads/activities/gallery-desert-1.webp","/uploads/activities/gallery-desert-2.webp","/uploads/activities/gallery-desert-3.webp","/uploads/activities/gallery-desert-4.webp","/uploads/activities/gallery-desert-5.webp","/uploads/activities/gallery-desert-6.webp"]', '[]', '["4x4 hotel pick-up (~03:00 PM) & next-morning drop-off (~08:30 AM)","Full evening desert safari: red dune bashing, sunset photo stop & camel ride","BBQ buffet dinner with grilled meats, salads, desserts & unlimited soft drinks","Live evening entertainment: Tanoura dance, belly dance show & fire performance","Overnight Bedouin tent stay with comfortable mattress, fresh linens, pillows & blankets","Freshly prepared Arabian sunrise breakfast with eggs, warm bread, cheese, tea & Arabic Gahwa coffee","Morning sunrise viewing across tranquil open desert dunes"]', '["Quad biking","Alcoholic beverages","Tips and personal expenses"]', 'Pick-up 02:45 PM – 03:30 PM; return next morning by 08:30 AM – 09:00 AM. Available from Dubai, Sharjah, and Abu Dhabi hotels.', 'Daily', '[{"q":"How do I confirm my booking for Overnight Desert Safari?","a":"Click \'Book on WhatsApp\' or submit the enquiry form below. Our UAE team replies within minutes on WhatsApp (+971 52 537 6838) with instant confirmation."},{"q":"Is hotel pick-up available?","a":"Hotel pick-up is included on most safari and sightseeing tours, and can be added to any cruise, watersport, or attraction ticket on WhatsApp."},{"q":"What is the cancellation policy?","a":"Free cancellation up to 48 hours before pick-up."}]', 1, 0, 3, 0, 'Overnight Desert Safari | Book Online & WhatsApp — Anchor Point UAE', 'Evening safari plus a night in a desert camp with breakfast. Duration: 18 hours. From AED 380 per person. Instant confirmation on WhatsApp.', '2026-11-02 09:52:01', '2026-11-02 09:52:01', '18 hours, hotel pick-up', 1, 310.0, 'Adults 12+ yrs | Children 5–11 yrs (Minimum age 5 yrs)', '{"overview":"Experience the quiet magic of the Arabian desert after all evening visitors depart. Enjoy the full Evening Desert Safari & BBQ Dinner, sleep comfortably in a traditional desert tent beneath a star-filled sky, and wake to golden sunrise views with freshly prepared breakfast.","timings_pickup":"Pick-up 02:45 PM – 03:30 PM; return next morning by 08:30 AM – 09:00 AM. Available from Dubai, Sharjah, and Abu Dhabi hotels.","important_notes":"Not recommended for pregnant guests or travellers with severe back problems. Bring a light jacket between November and March as desert nights are cool.","cancellation":"Free cancellation up to 48 hours before pick-up.","reviews":[{"author":"Claire M. (France)","rating":5,"comment":"Waking up to total silence on golden dunes with hot Arabic coffee was the highlight of our UAE trip."}]}');
INSERT INTO `tours` (`id`, `category_id`, `title`, `slug`, `badge`, `short_desc`, `long_desc`, `duration`, `price_aed`, `original_price_aed`, `rating`, `reviews_count`, `featured_image`, `gallery_json`, `itinerary_json`, `inclusions_json`, `exclusions_json`, `pickup_details`, `availability`, `faq_json`, `is_featured`, `is_combo`, `sort_order`, `is_active`, `seo_title`, `seo_desc`, `created_at`, `updated_at`, `pickup_line`, `has_pickup`, `child_price_aed`, `age_policy`, `details_json`) VALUES (4, 1, 'VIP Private Desert Safari', 'vip-private-desert-safari', '', 'Private 4x4, private camp area and premium dinner for your group', 'Designed for families, couples, and small groups seeking privacy and comfort. Travel in your own dedicated 4x4 at your preferred time, skip buffet queues completely, and enjoy waiter-served premium BBQ dining in a reserved VIP lounge facing the stage.', '6 hours', 320.0, NULL, 4.9, 123, '/uploads/activities/vip-private-desert-safari-cover.webp', '["/uploads/activities/vip-private-desert-safari-cover.webp","/uploads/activities/gallery-desert-1.webp","/uploads/activities/gallery-desert-2.webp","/uploads/activities/gallery-desert-3.webp","/uploads/activities/gallery-desert-4.webp","/uploads/activities/gallery-desert-5.webp","/uploads/activities/gallery-desert-6.webp"]', '[]', '["Exclusive private 4x4 Land Cruiser for your group","Custom dune-bashing intensity, camel ride & sunset stop","Reserved VIP majlis seating area with dedicated table waiter","Premium grilled BBQ platter, mezze, fruits, desserts & soft drinks","All live desert camp shows"]', '["Quad bikes & dune buggies","Professional photo frames","Tips"]', 'Flexible afternoon pick-up between 02:30 PM – 03:30 PM from any hotel or residence in Dubai, Sharjah, or Abu Dhabi.', 'Daily', '[{"q":"How do I confirm my booking for VIP Private Desert Safari?","a":"Click \'Book on WhatsApp\' or submit the enquiry form below. Our UAE team replies within minutes on WhatsApp (+971 52 537 6838) with instant confirmation."},{"q":"Is hotel pick-up available?","a":"Hotel pick-up is included on most safari and sightseeing tours, and can be added to any cruise, watersport, or attraction ticket on WhatsApp."},{"q":"What is the cancellation policy?","a":"Free cancellation up to 24 hours before scheduled pick-up."}]', 1, 0, 4, 1, 'VIP Private Desert Safari | Book Online & WhatsApp — Anchor Point UAE', 'Private 4x4, private camp area and premium dinner for your group. Duration: 6 hours. From AED 320 per person. Instant confirmation on WhatsApp.', '2026-11-02 09:52:01', '2026-11-02 09:52:01', '6 hours, private 4x4 pick-up', 1, 250.0, 'All ages welcome (Private 4x4 adjusts driving pace to your family)', '{"overview":"Designed for families, couples, and small groups seeking privacy and comfort. Travel in your own dedicated 4x4 at your preferred time, skip buffet queues completely, and enjoy waiter-served premium BBQ dining in a reserved VIP lounge facing the stage.","timings_pickup":"Flexible afternoon pick-up between 02:30 PM – 03:30 PM from any hotel or residence in Dubai, Sharjah, or Abu Dhabi.","important_notes":"Because the 4x4 is private, dune bashing can be made gentle or skipped altogether for families with young children or seniors.","cancellation":"Free cancellation up to 24 hours before scheduled pick-up.","reviews":[{"author":"Omar A. (Saudi Arabia)","rating":5,"comment":"Private Land Cruiser and VIP majlis service made it effortless with our kids and parents."}]}');
INSERT INTO `tours` (`id`, `category_id`, `title`, `slug`, `badge`, `short_desc`, `long_desc`, `duration`, `price_aed`, `original_price_aed`, `rating`, `reviews_count`, `featured_image`, `gallery_json`, `itinerary_json`, `inclusions_json`, `exclusions_json`, `pickup_details`, `availability`, `faq_json`, `is_featured`, `is_combo`, `sort_order`, `is_active`, `seo_title`, `seo_desc`, `created_at`, `updated_at`, `pickup_line`, `has_pickup`, `child_price_aed`, `age_policy`, `details_json`) VALUES (5, 1, 'Quad Bike Desert Safari', 'quad-bike-desert-safari', '', 'Guided quad bike ride across the dunes, add-on to any safari', 'Take control of an automatic all-terrain quad bike and follow an experienced desert marshal across open Lahbab sand bowls and ridges. Bookable as a dedicated morning/afternoon ride with transfer or added directly onto any safari.', '1 hour', 220.0, NULL, 4.9, 130, '/uploads/activities/quad-bike-desert-safari-cover.webp', '["/uploads/activities/quad-bike-desert-safari-cover.webp","/uploads/activities/gallery-desert-1.webp","/uploads/activities/gallery-desert-2.webp","/uploads/activities/gallery-desert-3.webp","/uploads/activities/gallery-desert-4.webp","/uploads/activities/gallery-desert-5.webp","/uploads/activities/gallery-desert-6.webp"]', '[]', '["Return hotel transfer or seamless add-on to Morning/Evening Safari","60-minute guided automatic ATV quad bike ride on open red dunes","Safety helmet, goggles, briefing & desert lead marshal","Cold bottled water & sandboarding pause"]', '["Damage insurance waiver","Camp BBQ dinner unless combined with Evening Safari","Tips"]', 'Morning (08:00 AM), Afternoon (02:30 PM), or Sunset slots daily. Pick-up from Dubai & Sharjah hotels.', 'Daily', '[{"q":"How do I confirm my booking for Quad Bike Desert Safari?","a":"Click \'Book on WhatsApp\' or submit the enquiry form below. Our UAE team replies within minutes on WhatsApp (+971 52 537 6838) with instant confirmation."},{"q":"Is hotel pick-up available?","a":"Hotel pick-up is included on most safari and sightseeing tours, and can be added to any cruise, watersport, or attraction ticket on WhatsApp."},{"q":"What is the cancellation policy?","a":"Free cancellation up to 24 hours in advance."}]', 0, 0, 5, 0, 'Quad Bike Desert Safari | Book Online & WhatsApp — Anchor Point UAE', 'Guided quad bike ride across the dunes, add-on to any safari. Duration: 1 hour. From AED 220 per person. Instant confirmation on WhatsApp.', '2026-11-02 09:52:01', '2026-11-02 09:52:01', '1 hour ride, hotel pick-up', 1, 180.0, 'Riders 16+ yrs for open-desert ATV (10–15 yrs in supervised circuit)', '{"overview":"Take control of an automatic all-terrain quad bike and follow an experienced desert marshal across open Lahbab sand bowls and ridges. Bookable as a dedicated morning/afternoon ride with transfer or added directly onto any safari.","timings_pickup":"Morning (08:00 AM), Afternoon (02:30 PM), or Sunset slots daily. Pick-up from Dubai & Sharjah hotels.","important_notes":"Closed-toe shoes recommended. Not permitted for pregnant guests or guests with back/neck injuries.","cancellation":"Free cancellation up to 24 hours in advance.","reviews":[{"author":"Liam T. (Australia)","rating":5,"comment":"Proper open-desert dunes—not a tiny fenced pen! 60 full minutes of riding."}]}');
INSERT INTO `tours` (`id`, `category_id`, `title`, `slug`, `badge`, `short_desc`, `long_desc`, `duration`, `price_aed`, `original_price_aed`, `rating`, `reviews_count`, `featured_image`, `gallery_json`, `itinerary_json`, `inclusions_json`, `exclusions_json`, `pickup_details`, `availability`, `faq_json`, `is_featured`, `is_combo`, `sort_order`, `is_active`, `seo_title`, `seo_desc`, `created_at`, `updated_at`, `pickup_line`, `has_pickup`, `child_price_aed`, `age_policy`, `details_json`) VALUES (6, 1, 'Hot Air Balloon and Desert Breakfast', 'hot-air-balloon-and-desert-breakfast', '', 'Sunrise balloon flight over the desert followed by breakfast', 'Float silently up to 4,000 feet above untouched red dunes as the sun rises over the Hajar Mountains. After landing, celebrate at a serene desert oasis camp with a gourmet breakfast spread before returning to your hotel.', '5 hours', 990.0, NULL, 4.9, 137, '/uploads/activities/hot-air-balloon-and-desert-breakfast-cover.webp', '["/uploads/activities/hot-air-balloon-and-desert-breakfast-cover.webp","/uploads/activities/gallery-desert-1.webp","/uploads/activities/gallery-desert-2.webp","/uploads/activities/gallery-desert-3.webp","/uploads/activities/gallery-desert-4.webp","/uploads/activities/gallery-desert-5.webp","/uploads/activities/gallery-desert-6.webp"]', '[]', '["Pre-dawn hotel pick-up & drop-off in Dubai","45–60 minute sunrise hot air balloon flight up to 4,000 ft","Spotting Arabian oryx & gazelles over Margham desert","Gourmet Bedouin camp breakfast & flight certificate"]', '["In-flight drone/video package (optional)","Abu Dhabi hotel transfer supplement","Tips"]', 'Pick-up between 04:00 AM – 04:45 AM (exact time confirmed on WhatsApp the evening prior); return by 09:30 AM.', 'Daily', '[{"q":"How do I confirm my booking for Hot Air Balloon and Desert Breakfast?","a":"Click \'Book on WhatsApp\' or submit the enquiry form below. Our UAE team replies within minutes on WhatsApp (+971 52 537 6838) with instant confirmation."},{"q":"Is hotel pick-up available?","a":"Hotel pick-up is included on most safari and sightseeing tours, and can be added to any cruise, watersport, or attraction ticket on WhatsApp."},{"q":"What is the cancellation policy?","a":"Free cancellation up to 48 hours prior; 100% refund or free reschedule if cancelled due to wind/weather."}]', 0, 0, 6, 1, 'Hot Air Balloon and Desert Breakfast | Book Online & WhatsApp — Anchor Point UAE', 'Sunrise balloon flight over the desert followed by breakfast. Duration: 5 hours. From AED 990 per person. Instant confirmation on WhatsApp.', '2026-11-02 09:52:01', '2026-11-02 09:52:01', '5 hours, hotel pick-up', 1, 850.0, 'Adults 12–79 yrs | Children 5–11 yrs (Minimum age 5 yrs)', '{"overview":"Float silently up to 4,000 feet above untouched red dunes as the sun rises over the Hajar Mountains. After landing, celebrate at a serene desert oasis camp with a gourmet breakfast spread before returning to your hotel.","timings_pickup":"Pick-up between 04:00 AM – 04:45 AM (exact time confirmed on WhatsApp the evening prior); return by 09:30 AM.","important_notes":"Not permitted for pregnant guests, children under 5, or anyone who has scuba dived within 24 hours or had recent major surgery.","cancellation":"Free cancellation up to 48 hours prior; 100% refund or free reschedule if cancelled due to wind/weather.","reviews":[{"author":"Elena V. (Spain)","rating":5,"comment":"Watching Arabian oryx run across golden dunes from a sunrise balloon was pure magic."}]}');
INSERT INTO `tours` (`id`, `category_id`, `title`, `slug`, `badge`, `short_desc`, `long_desc`, `duration`, `price_aed`, `original_price_aed`, `rating`, `reviews_count`, `featured_image`, `gallery_json`, `itinerary_json`, `inclusions_json`, `exclusions_json`, `pickup_details`, `availability`, `faq_json`, `is_featured`, `is_combo`, `sort_order`, `is_active`, `seo_title`, `seo_desc`, `created_at`, `updated_at`, `pickup_line`, `has_pickup`, `child_price_aed`, `age_policy`, `details_json`) VALUES (7, 2, 'Dubai City Tour (Half Day)', 'dubai-city-tour-half-day', '', 'Burj Khalifa photo stop, Jumeirah Mosque, Dubai Frame, Palm view', 'Get a complete orientation to modern and coastal Dubai in one seamless morning or afternoon half-day guided tour—covering iconic skyline landmarks with plenty of guided photo stops.', '4 hours', 110.0, NULL, 4.9, 144, '/uploads/activities/dubai-city-tour-half-day-cover.webp', '["/uploads/activities/dubai-city-tour-half-day-cover.webp","/uploads/activities/gallery-city-1.webp","/uploads/activities/gallery-city-2.webp","/uploads/activities/gallery-city-3.webp","/uploads/activities/gallery-city-4.webp","/uploads/activities/gallery-city-5.webp","/uploads/activities/gallery-city-6.webp"]', '["Jumeirah Mosque exterior stop","Jumeirah Beach & Burj Al Arab photo stop","Palm Jumeirah Island & Atlantis The Palm view","Dubai Marina & Sheikh Zayed Road drive-pass","Dubai Frame & Museum of the Future exterior stop","Downtown Dubai & Burj Khalifa photo stop"]', '["Air-conditioned coach/minivan hotel pick-up & drop-off","Licensed English-speaking UAE tour guide","Photo stops at Burj Khalifa/Downtown, Museum of the Future, Dubai Frame, Jumeirah Mosque, Burj Al Arab & Palm Jumeirah","Chilled bottled mineral water"]', '["Inside observation deck entry tickets (can be added on WhatsApp)","Meals & personal shopping","Tips"]', 'Morning departure 08:30 AM – 09:00 AM or Afternoon 02:00 PM. Hotel pick-up across Dubai & Sharjah.', 'Daily', '[{"q":"How do I confirm my booking for Dubai City Tour (Half Day)?","a":"Click \'Book on WhatsApp\' or submit the enquiry form below. Our UAE team replies within minutes on WhatsApp (+971 52 537 6838) with instant confirmation."},{"q":"Is hotel pick-up available?","a":"Hotel pick-up is included on most safari and sightseeing tours, and can be added to any cruise, watersport, or attraction ticket on WhatsApp."},{"q":"What is the cancellation policy?","a":"Free cancellation up to 24 hours before tour start."}]', 1, 0, 1, 1, 'Dubai City Tour (Half Day) | Book Online & WhatsApp — Anchor Point UAE', 'Burj Khalifa photo stop, Jumeirah Mosque, Dubai Frame, Palm view. Duration: 4 hours. From AED 110 per person. Instant confirmation on WhatsApp.', '2026-11-02 09:52:01', '2026-11-02 09:52:01', '4 hours, hotel pick-up', 1, 85.0, 'Adults 12+ yrs | Children 3–11 yrs | Under 3 free', '{"overview":"Get a complete orientation to modern and coastal Dubai in one seamless morning or afternoon half-day guided tour—covering iconic skyline landmarks with plenty of guided photo stops.","route_stops":["Jumeirah Mosque exterior stop","Jumeirah Beach & Burj Al Arab photo stop","Palm Jumeirah Island & Atlantis The Palm view","Dubai Marina & Sheikh Zayed Road drive-pass","Dubai Frame & Museum of the Future exterior stop","Downtown Dubai & Burj Khalifa photo stop"],"timings_pickup":"Morning departure 08:30 AM – 09:00 AM or Afternoon 02:00 PM. Hotel pick-up across Dubai & Sharjah.","dress_code":"Smart casual comfortable clothing; modest shoulder-and-knee coverage recommended if stepping near mosque courtyards.","cancellation":"Free cancellation up to 24 hours before tour start.","reviews":[{"author":"James B. (UK)","rating":5,"comment":"Ideal first-day overview of Dubai—clean AC van, knowledgeable guide, and great photo stops."}]}');
INSERT INTO `tours` (`id`, `category_id`, `title`, `slug`, `badge`, `short_desc`, `long_desc`, `duration`, `price_aed`, `original_price_aed`, `rating`, `reviews_count`, `featured_image`, `gallery_json`, `itinerary_json`, `inclusions_json`, `exclusions_json`, `pickup_details`, `availability`, `faq_json`, `is_featured`, `is_combo`, `sort_order`, `is_active`, `seo_title`, `seo_desc`, `created_at`, `updated_at`, `pickup_line`, `has_pickup`, `child_price_aed`, `age_policy`, `details_json`) VALUES (8, 2, 'Old and New Dubai Tour', 'old-and-new-dubai-tour', '', 'Al Fahidi district, abra boat ride, gold and spice souks, modern downtown', 'Trace Dubai\'s story from pearl-diving creek settlement to futuristic metropolis. Stroll wind-tower lanes in Al Fahidi, cross Dubai Creek on a wooden abra, smell saffron and frankincense in the Spice Souk, and finish beneath the gleaming towers of Sheikh Zayed Road and Downtown.', '5 hours', 145.0, NULL, 4.9, 151, '/uploads/activities/old-and-new-dubai-tour-cover.webp', '["/uploads/activities/old-and-new-dubai-tour-cover.webp","/uploads/activities/gallery-city-1.webp","/uploads/activities/gallery-city-2.webp","/uploads/activities/gallery-city-3.webp","/uploads/activities/gallery-city-4.webp","/uploads/activities/gallery-city-5.webp","/uploads/activities/gallery-city-6.webp"]', '["Al Fahidi Historical District & wind-tower courtyards","Traditional Abra boat crossing on Dubai Creek","Deira Spice Souk & Gold Souk guided walk","Dubai Frame & Museum of the Future photo stop","Downtown Dubai & Burj Khalifa"]', '["Hotel pick-up & drop-off in air-conditioned vehicle","Licensed heritage & city tour guide","Traditional wooden Abra water-taxi ticket across Dubai Creek","Guided walk in Al Fahidi Historical Neighbourhood, Gold Souk & Spice Souk","Modern Dubai drive & Downtown photo stops + bottled water"]', '["Optional inside museum entry tickets & meals","Souk shopping","Tips"]', 'Daily pick-up 09:00 AM – 09:30 AM from Dubai & Sharjah hotels.', 'Daily', '[{"q":"How do I confirm my booking for Old and New Dubai Tour?","a":"Click \'Book on WhatsApp\' or submit the enquiry form below. Our UAE team replies within minutes on WhatsApp (+971 52 537 6838) with instant confirmation."},{"q":"Is hotel pick-up available?","a":"Hotel pick-up is included on most safari and sightseeing tours, and can be added to any cruise, watersport, or attraction ticket on WhatsApp."},{"q":"What is the cancellation policy?","a":"Free cancellation up to 24 hours before departure."}]', 1, 0, 2, 1, 'Old and New Dubai Tour | Book Online & WhatsApp — Anchor Point UAE', 'Al Fahidi district, abra boat ride, gold and spice souks, modern downtown. Duration: 5 hours. From AED 145 per person. Instant confirmation on WhatsApp.', '2026-11-02 09:52:01', '2026-11-02 09:52:01', '5 hours, hotel pick-up', 1, 110.0, 'Adults 12+ yrs | Children 3–11 yrs | Under 3 free', '{"overview":"Trace Dubai\'s story from pearl-diving creek settlement to futuristic metropolis. Stroll wind-tower lanes in Al Fahidi, cross Dubai Creek on a wooden abra, smell saffron and frankincense in the Spice Souk, and finish beneath the gleaming towers of Sheikh Zayed Road and Downtown.","route_stops":["Al Fahidi Historical District & wind-tower courtyards","Traditional Abra boat crossing on Dubai Creek","Deira Spice Souk & Gold Souk guided walk","Dubai Frame & Museum of the Future photo stop","Downtown Dubai & Burj Khalifa"],"timings_pickup":"Daily pick-up 09:00 AM – 09:30 AM from Dubai & Sharjah hotels.","dress_code":"Comfortable walking shoes and light modest attire suitable for historic heritage quarters.","cancellation":"Free cancellation up to 24 hours before departure.","reviews":[{"author":"Nadia L. (Canada)","rating":5,"comment":"Crossing the Creek by abra and exploring Al Fahidi with a local guide brought Dubai\'s history alive."}]}');
INSERT INTO `tours` (`id`, `category_id`, `title`, `slug`, `badge`, `short_desc`, `long_desc`, `duration`, `price_aed`, `original_price_aed`, `rating`, `reviews_count`, `featured_image`, `gallery_json`, `itinerary_json`, `inclusions_json`, `exclusions_json`, `pickup_details`, `availability`, `faq_json`, `is_featured`, `is_combo`, `sort_order`, `is_active`, `seo_title`, `seo_desc`, `created_at`, `updated_at`, `pickup_line`, `has_pickup`, `child_price_aed`, `age_policy`, `details_json`) VALUES (9, 2, 'Abu Dhabi City Tour', 'abu-dhabi-city-tour', '', 'Sheikh Zayed Grand Mosque, Corniche, Emirates Palace photo stop, Heritage Village', 'Discover the UAE capital on a full-day guided journey from Dubai. Marvel at the white marble domes and Swarovski chandeliers of Sheikh Zayed Grand Mosque, drive the turquoise Corniche, pause for photos at Emirates Palace, and explore traditional Emirati crafts at Heritage Village.', '9 hours', 175.0, NULL, 4.9, 158, '/uploads/activities/abu-dhabi-city-tour-cover.webp', '["/uploads/activities/abu-dhabi-city-tour-cover.webp","/uploads/activities/gallery-city-1.webp","/uploads/activities/gallery-city-2.webp","/uploads/activities/gallery-city-3.webp","/uploads/activities/gallery-city-4.webp","/uploads/activities/gallery-city-5.webp","/uploads/activities/gallery-city-6.webp"]', '["Sheikh Zayed Grand Mosque (inside guided visit)","Emirates Palace Mandarin Oriental photo stop","Abu Dhabi Corniche waterfront","Abu Dhabi Heritage Village","Abu Dhabi Dates Market","Yas Island Ferrari World exterior photo stop"]', '["Round-trip AC transport from Dubai or Abu Dhabi hotels","Sheikh Zayed Grand Mosque guided entry visit","Abu Dhabi Corniche, Emirates Palace photo stop & Heritage Village","Dates Market & Yas Island Ferrari World photo stop","Licensed guide & bottled water"]', '["Lunch (1-hour stop at Marina Mall food court/restaurants)","Qasr Al Watan or Louvre inside tickets (available as upgrade)","Tips"]', 'Daily pick-up 08:00 AM – 08:30 AM from Dubai hotels (09:30 AM in Abu Dhabi); return ~05:30 PM.', 'Daily', '[{"q":"How do I confirm my booking for Abu Dhabi City Tour?","a":"Click \'Book on WhatsApp\' or submit the enquiry form below. Our UAE team replies within minutes on WhatsApp (+971 52 537 6838) with instant confirmation."},{"q":"Is hotel pick-up available?","a":"Hotel pick-up is included on most safari and sightseeing tours, and can be added to any cruise, watersport, or attraction ticket on WhatsApp."},{"q":"What is the cancellation policy?","a":"Free cancellation up to 24 hours before pick-up."}]', 1, 0, 3, 1, 'Abu Dhabi City Tour | Book Online & WhatsApp — Anchor Point UAE', 'Sheikh Zayed Grand Mosque, Corniche, Emirates Palace photo stop, Heritage Village. Duration: 9 hours. From AED 175 per person. Instant confirmation on WhatsApp.', '2026-11-02 09:52:01', '2026-11-02 09:52:01', '9 hours, hotel pick-up', 1, 140.0, 'Adults 12+ yrs | Children 3–11 yrs | Under 3 free', '{"overview":"Discover the UAE capital on a full-day guided journey from Dubai. Marvel at the white marble domes and Swarovski chandeliers of Sheikh Zayed Grand Mosque, drive the turquoise Corniche, pause for photos at Emirates Palace, and explore traditional Emirati crafts at Heritage Village.","route_stops":["Sheikh Zayed Grand Mosque (inside guided visit)","Emirates Palace Mandarin Oriental photo stop","Abu Dhabi Corniche waterfront","Abu Dhabi Heritage Village","Abu Dhabi Dates Market","Yas Island Ferrari World exterior photo stop"],"timings_pickup":"Daily pick-up 08:00 AM – 08:30 AM from Dubai hotels (09:30 AM in Abu Dhabi); return ~05:30 PM.","dress_code":"Strict Mosque Dress Code: Women must wear loose ankle-length trousers/skirt, long sleeves to wrists, and a headscarf; Men must wear long trousers and covered shoulders (no shorts or sleeveless tops).","cancellation":"Free cancellation up to 24 hours before pick-up.","reviews":[{"author":"Sophia G. (USA)","rating":5,"comment":"Sheikh Zayed Grand Mosque took our breath away. Well-paced full day with smooth hotel transfers."}]}');
INSERT INTO `tours` (`id`, `category_id`, `title`, `slug`, `badge`, `short_desc`, `long_desc`, `duration`, `price_aed`, `original_price_aed`, `rating`, `reviews_count`, `featured_image`, `gallery_json`, `itinerary_json`, `inclusions_json`, `exclusions_json`, `pickup_details`, `availability`, `faq_json`, `is_featured`, `is_combo`, `sort_order`, `is_active`, `seo_title`, `seo_desc`, `created_at`, `updated_at`, `pickup_line`, `has_pickup`, `child_price_aed`, `age_policy`, `details_json`) VALUES (10, 2, 'Sharjah and Ajman Tour', 'sharjah-and-ajman-tour', '', 'Sharjah heritage area, museums, souks and Ajman Corniche', 'Visit UNESCO-recognized Sharjah—the Cultural Capital of the Arab World—alongside neighbouring coastal Ajman. Explore traditional coral-stone architecture, bustling carpet and silver souks, grand mosques, and the breezy Ajman Corniche.', '6 hours', 165.0, NULL, 4.9, 165, '/uploads/activities/sharjah-and-ajman-tour-cover.webp', '["/uploads/activities/sharjah-and-ajman-tour-cover.webp","/uploads/activities/gallery-city-1.webp","/uploads/activities/gallery-city-2.webp","/uploads/activities/gallery-city-3.webp","/uploads/activities/gallery-city-4.webp","/uploads/activities/gallery-city-5.webp","/uploads/activities/gallery-city-6.webp"]', '["Sharjah Mosque / King Faisal Mosque photo stop","Heart of Sharjah & Souk Al Arsah","Sharjah Museum of Islamic Civilization exterior / optional visit","Central Souk (Blue Souk)","Ajman Corniche waterfront"]', '["Hotel pick-up & drop-off from Dubai, Sharjah or Ajman","Licensed cultural tour guide","Heart of Sharjah heritage area, Blue Souk & Souk Al Arsah","King Faisal Mosque & Sharjah Mosque photo stops + Ajman Corniche","Bottled water"]', '["Optional museum entry fees","Meals","Tips"]', 'Pick-up 08:30 AM – 09:00 AM (Sun–Thu & Sat); return ~02:30 PM.', 'Daily', '[{"q":"How do I confirm my booking for Sharjah and Ajman Tour?","a":"Click \'Book on WhatsApp\' or submit the enquiry form below. Our UAE team replies within minutes on WhatsApp (+971 52 537 6838) with instant confirmation."},{"q":"Is hotel pick-up available?","a":"Hotel pick-up is included on most safari and sightseeing tours, and can be added to any cruise, watersport, or attraction ticket on WhatsApp."},{"q":"What is the cancellation policy?","a":"Free cancellation up to 24 hours in advance."}]', 1, 0, 4, 1, 'Sharjah and Ajman Tour | Book Online & WhatsApp — Anchor Point UAE', 'Sharjah heritage area, museums, souks and Ajman Corniche. Duration: 6 hours. From AED 165 per person. Instant confirmation on WhatsApp.', '2026-11-02 09:52:01', '2026-11-02 09:52:01', '6 hours, hotel pick-up', 1, 130.0, 'Adults 12+ yrs | Children 3–11 yrs', '{"overview":"Visit UNESCO-recognized Sharjah—the Cultural Capital of the Arab World—alongside neighbouring coastal Ajman. Explore traditional coral-stone architecture, bustling carpet and silver souks, grand mosques, and the breezy Ajman Corniche.","route_stops":["Sharjah Mosque / King Faisal Mosque photo stop","Heart of Sharjah & Souk Al Arsah","Sharjah Museum of Islamic Civilization exterior / optional visit","Central Souk (Blue Souk)","Ajman Corniche waterfront"],"timings_pickup":"Pick-up 08:30 AM – 09:00 AM (Sun–Thu & Sat); return ~02:30 PM.","dress_code":"Modest dress covering shoulders and knees is appreciated across Sharjah\'s cultural districts.","cancellation":"Free cancellation up to 24 hours in advance.","reviews":[{"author":"Tariq M. (UK)","rating":5,"comment":"A wonderful cultural contrast to Downtown Dubai—loved the Blue Souk and Sharjah heritage lanes."}]}');
INSERT INTO `tours` (`id`, `category_id`, `title`, `slug`, `badge`, `short_desc`, `long_desc`, `duration`, `price_aed`, `original_price_aed`, `rating`, `reviews_count`, `featured_image`, `gallery_json`, `itinerary_json`, `inclusions_json`, `exclusions_json`, `pickup_details`, `availability`, `faq_json`, `is_featured`, `is_combo`, `sort_order`, `is_active`, `seo_title`, `seo_desc`, `created_at`, `updated_at`, `pickup_line`, `has_pickup`, `child_price_aed`, `age_policy`, `details_json`) VALUES (11, 2, 'Private City Tour with Driver', 'private-city-tour-with-driver', '', 'Your own car and guide, you choose the stops', 'Explore the UAE at your own pace with a private air-conditioned SUV and experienced local driver. Choose a 4-hour half-day or 8-hour full-day charter and tailor every stop around your family\'s wish list.', '4 to 8 hours', 490.0, NULL, 4.9, 172, '/uploads/activities/private-city-tour-with-driver-cover.webp', '["/uploads/activities/private-city-tour-with-driver-cover.webp","/uploads/activities/gallery-city-1.webp","/uploads/activities/gallery-city-2.webp","/uploads/activities/gallery-city-3.webp","/uploads/activities/gallery-city-4.webp","/uploads/activities/gallery-city-5.webp","/uploads/activities/gallery-city-6.webp"]', '["100% flexible — Old Dubai, Downtown, Palm Jumeirah, Dubai Marina, Miracle Garden, or Abu Dhabi landmarks"]', '["Private modern SUV/minivan with English-speaking driver-guide","100% customizable itinerary in Dubai, Abu Dhabi, or Sharjah","Door-to-door pick-up & drop-off at hotel, cruise port, or airport","Fuel, Salik tolls, parking & chilled bottled water"]', '["Paid attraction entry tickets","Meals","Licensed multi-language walking guide upgrade (optional)"]', 'Flexible start time (morning, afternoon, or evening) from any Dubai, Sharjah, or Abu Dhabi address.', 'Daily', '[{"q":"How do I confirm my booking for Private City Tour with Driver?","a":"Click \'Book on WhatsApp\' or submit the enquiry form below. Our UAE team replies within minutes on WhatsApp (+971 52 537 6838) with instant confirmation."},{"q":"Is hotel pick-up available?","a":"Hotel pick-up is included on most safari and sightseeing tours, and can be added to any cruise, watersport, or attraction ticket on WhatsApp."},{"q":"What is the cancellation policy?","a":"Free cancellation up to 24 hours prior."}]', 0, 0, 5, 1, 'Private City Tour with Driver | Book Online & WhatsApp — Anchor Point UAE', 'Your own car and guide, you choose the stops. Duration: 4 to 8 hours. From AED 490 per person. Instant confirmation on WhatsApp.', '2026-11-02 09:52:01', '2026-11-02 09:52:01', '4 to 8 hours, private car pick-up', 1, 0.0, 'Private vehicle rate up to 6 guests (Child seats available on request)', '{"overview":"Explore the UAE at your own pace with a private air-conditioned SUV and experienced local driver. Choose a 4-hour half-day or 8-hour full-day charter and tailor every stop around your family\'s wish list.","route_stops":["100% flexible — Old Dubai, Downtown, Palm Jumeirah, Dubai Marina, Miracle Garden, or Abu Dhabi landmarks"],"timings_pickup":"Flexible start time (morning, afternoon, or evening) from any Dubai, Sharjah, or Abu Dhabi address.","dress_code":"Casual attire; modest cover required only if visiting mosques.","cancellation":"Free cancellation up to 24 hours prior.","reviews":[{"author":"Victoria H. (Switzerland)","rating":5,"comment":"So convenient with elderly parents—immaculate SUV and we covered every landmark without rushing."}]}');
INSERT INTO `tours` (`id`, `category_id`, `title`, `slug`, `badge`, `short_desc`, `long_desc`, `duration`, `price_aed`, `original_price_aed`, `rating`, `reviews_count`, `featured_image`, `gallery_json`, `itinerary_json`, `inclusions_json`, `exclusions_json`, `pickup_details`, `availability`, `faq_json`, `is_featured`, `is_combo`, `sort_order`, `is_active`, `seo_title`, `seo_desc`, `created_at`, `updated_at`, `pickup_line`, `has_pickup`, `child_price_aed`, `age_policy`, `details_json`) VALUES (12, 2, 'Dubai Night Lights Tour', 'dubai-night-lights-tour', '', 'Evening drive past illuminated landmarks with photo stops', 'See Dubai transform after dark when skyscrapers, bridges, and waterfront promenades light up the night sky. Includes prime evening photo stops and watching the choreographed Dubai Fountain show beneath Burj Khalifa.', '3 hours', 135.0, NULL, 4.9, 179, '/uploads/activities/dubai-night-lights-tour-cover.webp', '["/uploads/activities/dubai-night-lights-tour-cover.webp","/uploads/activities/gallery-city-1.webp","/uploads/activities/gallery-city-2.webp","/uploads/activities/gallery-city-3.webp","/uploads/activities/gallery-city-4.webp","/uploads/activities/gallery-city-5.webp","/uploads/activities/gallery-city-6.webp"]', '["Dubai Marina illuminated waterfront walk","Palm Jumeirah & Atlantis night viewpoint","Souk Madinat Jumeirah & Burj Al Arab view","Museum of the Future lit calligraphy facade","Dubai Fountain & Burj Khalifa LED show"]', '["Evening hotel pick-up & drop-off in Dubai","Guided drive along illuminated Sheikh Zayed Road","Photo stops at Dubai Marina promenade, Madinat Jumeirah / Burj Al Arab, Museum of the Future & Dubai Fountain show","Bottled water"]', '["Dinner & paid observation deck tickets","Tips"]', 'Daily pick-up 06:30 PM – 07:00 PM; drop-off around 10:00 PM.', 'Daily', '[{"q":"How do I confirm my booking for Dubai Night Lights Tour?","a":"Click \'Book on WhatsApp\' or submit the enquiry form below. Our UAE team replies within minutes on WhatsApp (+971 52 537 6838) with instant confirmation."},{"q":"Is hotel pick-up available?","a":"Hotel pick-up is included on most safari and sightseeing tours, and can be added to any cruise, watersport, or attraction ticket on WhatsApp."},{"q":"What is the cancellation policy?","a":"Free cancellation up to 24 hours before pick-up."}]', 0, 0, 6, 1, 'Dubai Night Lights Tour | Book Online & WhatsApp — Anchor Point UAE', 'Evening drive past illuminated landmarks with photo stops. Duration: 3 hours. From AED 135 per person. Instant confirmation on WhatsApp.', '2026-11-02 09:52:01', '2026-11-02 09:52:01', '3 hours, hotel pick-up', 1, 100.0, 'Adults 12+ yrs | Children 3–11 yrs | Under 3 free', '{"overview":"See Dubai transform after dark when skyscrapers, bridges, and waterfront promenades light up the night sky. Includes prime evening photo stops and watching the choreographed Dubai Fountain show beneath Burj Khalifa.","route_stops":["Dubai Marina illuminated waterfront walk","Palm Jumeirah & Atlantis night viewpoint","Souk Madinat Jumeirah & Burj Al Arab view","Museum of the Future lit calligraphy facade","Dubai Fountain & Burj Khalifa LED show"],"timings_pickup":"Daily pick-up 06:30 PM – 07:00 PM; drop-off around 10:00 PM.","dress_code":"Smart casual evening attire.","cancellation":"Free cancellation up to 24 hours before pick-up.","reviews":[{"author":"Carlos D. (Brazil)","rating":5,"comment":"Dubai at night looks like a sci-fi movie—Museum of the Future and the Fountain stop were amazing."}]}');
INSERT INTO `tours` (`id`, `category_id`, `title`, `slug`, `badge`, `short_desc`, `long_desc`, `duration`, `price_aed`, `original_price_aed`, `rating`, `reviews_count`, `featured_image`, `gallery_json`, `itinerary_json`, `inclusions_json`, `exclusions_json`, `pickup_details`, `availability`, `faq_json`, `is_featured`, `is_combo`, `sort_order`, `is_active`, `seo_title`, `seo_desc`, `created_at`, `updated_at`, `pickup_line`, `has_pickup`, `child_price_aed`, `age_policy`, `details_json`) VALUES (13, 3, 'Dhow Cruise Dinner, Dubai Marina', 'dhow-cruise-dinner-dubai-marina', '', 'Traditional wooden dhow, buffet dinner, soft drinks and live music', 'Glide past the glittering towers of Dubai Marina, JBR, and Ain Dubai aboard a handcrafted wooden Arabian dhow while enjoying an international buffet dinner and live Tanoura entertainment.', '2 hours', 135.0, NULL, 4.9, 186, '/uploads/activities/dhow-cruise-dinner-dubai-marina-cover.webp', '["/uploads/activities/dhow-cruise-dinner-dubai-marina-cover.webp","/uploads/activities/gallery-cruise-1.webp","/uploads/activities/gallery-cruise-2.webp","/uploads/activities/gallery-cruise-3.webp","/uploads/activities/gallery-cruise-4.webp","/uploads/activities/gallery-cruise-5.webp","/uploads/activities/gallery-cruise-6.webp"]', '[]', '["2-hour evening cruise through Dubai Marina, JBR & Bluewaters","Welcome Arabic coffee, dates & chilled juice","5-star international & Asian buffet dinner (veg & non-veg)","Unlimited water, tea, coffee & soft drinks","Live Tanoura show & background music"]', '["Hotel transfers if \'Direct Boarding\' selected (Private/shared hotel transfer available)","Alcoholic beverages (available on board)","Tips"]', 'Dubai Marina Pier 7 / Marina Promenade Berth — arrive by 08:00 PM for 08:30 PM departure (returns 10:30 PM). Map pin sent instantly on WhatsApp.', 'Daily', '[{"q":"How do I confirm my booking for Dhow Cruise Dinner, Dubai Marina?","a":"Click \'Book on WhatsApp\' or submit the enquiry form below. Our UAE team replies within minutes on WhatsApp (+971 52 537 6838) with instant confirmation."},{"q":"Is hotel pick-up available?","a":"Hotel pick-up is included on most safari and sightseeing tours, and can be added to any cruise, watersport, or attraction ticket on WhatsApp."},{"q":"What is the cancellation policy?","a":"Free cancellation up to 24 hours prior to sailing."}]', 1, 0, 1, 1, 'Dhow Cruise Dinner, Dubai Marina | Book Online & WhatsApp — Anchor Point UAE', 'Traditional wooden dhow, buffet dinner, soft drinks and live music. Duration: 2 hours. From AED 135 per person. Instant confirmation on WhatsApp.', '2026-11-02 09:52:01', '2026-11-02 09:52:01', '2 hours, optional hotel pick-up', 1, 95.0, 'Adults 11+ yrs | Children 3–10 yrs | Infants under 3 free', '{"overview":"Glide past the glittering towers of Dubai Marina, JBR, and Ain Dubai aboard a handcrafted wooden Arabian dhow while enjoying an international buffet dinner and live Tanoura entertainment.","boarding_point":"Dubai Marina Pier 7 / Marina Promenade Berth — arrive by 08:00 PM for 08:30 PM departure (returns 10:30 PM). Map pin sent instantly on WhatsApp.","menu_highlights":"Live pasta & grill station, Arabic mezze (hummus, moutabal, fattoush), butter chicken, grilled fish, veg biryani, kids\' nuggets & fries, Umm Ali & assorted pastries. Unlimited soft drinks, water, tea & coffee.","seating_options":"Open-air Upper Deck (panoramic skyline breeze) or Air-conditioned Glass-window Lower Deck.","entertainment":"Traditional illuminated Tanoura spinning dance show & lounge music.","dress_code":"Smart casual (light jacket recommended on upper deck in winter).","cancellation":"Free cancellation up to 24 hours prior to sailing.","reviews":[{"author":"Amelia P. (UK)","rating":5,"comment":"Upper deck views of Dubai Marina lit up at night were unbeatable. Delicious buffet!"}]}');
INSERT INTO `tours` (`id`, `category_id`, `title`, `slug`, `badge`, `short_desc`, `long_desc`, `duration`, `price_aed`, `original_price_aed`, `rating`, `reviews_count`, `featured_image`, `gallery_json`, `itinerary_json`, `inclusions_json`, `exclusions_json`, `pickup_details`, `availability`, `faq_json`, `is_featured`, `is_combo`, `sort_order`, `is_active`, `seo_title`, `seo_desc`, `created_at`, `updated_at`, `pickup_line`, `has_pickup`, `child_price_aed`, `age_policy`, `details_json`) VALUES (14, 3, 'Dhow Cruise Dinner, Dubai Creek', 'dhow-cruise-dinner-dubai-creek', '', 'Old Dubai skyline, buffet dinner, Tanoura show', 'Sail the historic waters of Dubai Creek where old wind-towers, Heritage Village, and wooden trading dhows meet illuminated Deira landmarks—complete with buffet dining and live Tanoura entertainment.', '2 hours', 85.0, NULL, 4.9, 193, '/uploads/activities/dhow-cruise-dinner-dubai-creek-cover.webp', '["/uploads/activities/dhow-cruise-dinner-dubai-creek-cover.webp","/uploads/activities/gallery-cruise-1.webp","/uploads/activities/gallery-cruise-2.webp","/uploads/activities/gallery-cruise-3.webp","/uploads/activities/gallery-cruise-4.webp","/uploads/activities/gallery-cruise-5.webp","/uploads/activities/gallery-cruise-6.webp"]', '[]', '["2-hour cruise along historic Dubai Creek (Deira & Bur Dubai)","Welcome drinks & Arabic dates","International buffet dinner (vegetarian & non-vegetarian)","Unlimited soft drinks, mineral water, tea & coffee","Live Tanoura cultural dance performance"]', '["Optional hotel pick-up & drop-off supplement","Specialty beverages","Tips"]', 'Al Seef / Deira Creek Dhow Wharfage — boarding at 07:45 PM, cruising 08:30 PM – 10:30 PM. Exact Google Maps pin shared via WhatsApp.', 'Daily', '[{"q":"How do I confirm my booking for Dhow Cruise Dinner, Dubai Creek?","a":"Click \'Book on WhatsApp\' or submit the enquiry form below. Our UAE team replies within minutes on WhatsApp (+971 52 537 6838) with instant confirmation."},{"q":"Is hotel pick-up available?","a":"Hotel pick-up is included on most safari and sightseeing tours, and can be added to any cruise, watersport, or attraction ticket on WhatsApp."},{"q":"What is the cancellation policy?","a":"Free cancellation up to 24 hours before cruise date."}]', 1, 0, 2, 0, 'Dhow Cruise Dinner, Dubai Creek | Book Online & WhatsApp — Anchor Point UAE', 'Old Dubai skyline, buffet dinner, Tanoura show. Duration: 2 hours. From AED 85 per person. Instant confirmation on WhatsApp.', '2026-11-02 09:52:01', '2026-11-02 09:52:01', '2 hours, optional hotel pick-up', 1, 65.0, 'Adults 11+ yrs | Children 3–10 yrs | Infants under 3 free', '{"overview":"Sail the historic waters of Dubai Creek where old wind-towers, Heritage Village, and wooden trading dhows meet illuminated Deira landmarks—complete with buffet dining and live Tanoura entertainment.","boarding_point":"Al Seef / Deira Creek Dhow Wharfage — boarding at 07:45 PM, cruising 08:30 PM – 10:30 PM. Exact Google Maps pin shared via WhatsApp.","menu_highlights":"Fresh salads, Arabic mezze, grilled kebabs, chicken curry, vegetarian noodles & dal, fresh fruit, and Arabic sweets with unlimited soft drinks.","seating_options":"Open-air Upper Deck or Air-conditioned Lower Deck.","entertainment":"Live Tanoura folkloric dance & traditional music.","dress_code":"Smart casual, family-friendly attire.","cancellation":"Free cancellation up to 24 hours before cruise date.","reviews":[{"author":"Rizwan K. (UAE)","rating":5,"comment":"Great value family evening along Al Seef and Old Dubai Creek."}]}');
INSERT INTO `tours` (`id`, `category_id`, `title`, `slug`, `badge`, `short_desc`, `long_desc`, `duration`, `price_aed`, `original_price_aed`, `rating`, `reviews_count`, `featured_image`, `gallery_json`, `itinerary_json`, `inclusions_json`, `exclusions_json`, `pickup_details`, `availability`, `faq_json`, `is_featured`, `is_combo`, `sort_order`, `is_active`, `seo_title`, `seo_desc`, `created_at`, `updated_at`, `pickup_line`, `has_pickup`, `child_price_aed`, `age_policy`, `details_json`) VALUES (15, 3, 'Luxury Yacht Dinner Cruise', 'luxury-yacht-dinner-cruise', '', 'Modern yacht with a 3-course set dinner and indoor and outdoor seating', 'Step aboard a sleek modern luxury yacht with panoramic glass lounges and an open-air sky deck. Dine on chef-prepared courses while cruising past Dubai Marina, Ain Dubai, and the illuminated Palm Jumeirah shoreline.', '2.5 hours', 260.0, NULL, 4.9, 200, '/uploads/activities/luxury-yacht-dinner-cruise-cover.webp', '["/uploads/activities/luxury-yacht-dinner-cruise-cover.webp","/uploads/activities/gallery-cruise-1.webp","/uploads/activities/gallery-cruise-2.webp","/uploads/activities/gallery-cruise-3.webp","/uploads/activities/gallery-cruise-4.webp","/uploads/activities/gallery-cruise-5.webp","/uploads/activities/gallery-cruise-6.webp"]', '[]', '["2.5-hour mega-yacht/modern glass-yacht cruise past Marina, JBR, Bluewaters & Palm crescent","Red-carpet boarding & welcome mocktail","3-course gourmet dinner / live chef stations (veg, non-veg & kids)","Indoor panoramic salon & open sky-deck lounge seating","Live saxophonist / acoustic vocalist & DJ"]', '["Premium house beverage upgrade package","Optional private hotel chauffeur transfer","Tips"]', 'Dubai Harbour / Pier 7 Yacht Marina — check-in 07:30 PM, sailing 08:00 PM – 10:30 PM.', 'Daily', '[{"q":"How do I confirm my booking for Luxury Yacht Dinner Cruise?","a":"Click \'Book on WhatsApp\' or submit the enquiry form below. Our UAE team replies within minutes on WhatsApp (+971 52 537 6838) with instant confirmation."},{"q":"Is hotel pick-up available?","a":"Hotel pick-up is included on most safari and sightseeing tours, and can be added to any cruise, watersport, or attraction ticket on WhatsApp."},{"q":"What is the cancellation policy?","a":"Free cancellation up to 24 hours prior."}]', 1, 0, 3, 1, 'Luxury Yacht Dinner Cruise | Book Online & WhatsApp — Anchor Point UAE', 'Modern yacht with a 3-course set dinner and indoor and outdoor seating. Duration: 2.5 hours. From AED 260 per person. Instant confirmation on WhatsApp.', '2026-11-02 09:52:01', '2026-11-02 09:52:01', '2.5 hours, Dubai Harbour boarding', 1, 190.0, 'Adults 12+ yrs | Children 4–11 yrs | Infants under 4 free', '{"overview":"Step aboard a sleek modern luxury yacht with panoramic glass lounges and an open-air sky deck. Dine on chef-prepared courses while cruising past Dubai Marina, Ain Dubai, and the illuminated Palm Jumeirah shoreline.","boarding_point":"Dubai Harbour / Pier 7 Yacht Marina — check-in 07:30 PM, sailing 08:00 PM – 10:30 PM.","menu_highlights":"Artisanal starters, grilled salmon or Angus beef/chicken main (plus gourmet vegetarian & kids\' pasta options), decadent chocolate dessert, mocktails & soft drinks.","seating_options":"Lower panoramic glass dining deck, Open Sky Deck lounge, or VIP reserved bow table.","entertainment":"Live acoustic/saxophone performance & ambient lounge DJ.","dress_code":"Smart elegant / resort evening wear (no flip-flops or swimwear).","cancellation":"Free cancellation up to 24 hours prior.","reviews":[{"author":"Lina S. (Sweden)","rating":5,"comment":"Five-star service, live saxophone on the upper deck, and incredible views of Ain Dubai."}]}');
INSERT INTO `tours` (`id`, `category_id`, `title`, `slug`, `badge`, `short_desc`, `long_desc`, `duration`, `price_aed`, `original_price_aed`, `rating`, `reviews_count`, `featured_image`, `gallery_json`, `itinerary_json`, `inclusions_json`, `exclusions_json`, `pickup_details`, `availability`, `faq_json`, `is_featured`, `is_combo`, `sort_order`, `is_active`, `seo_title`, `seo_desc`, `created_at`, `updated_at`, `pickup_line`, `has_pickup`, `child_price_aed`, `age_policy`, `details_json`) VALUES (16, 3, 'Private Yacht Dinner (Couples)', 'private-yacht-dinner-couples', '', 'Private table, decorated setup, ideal for proposals and anniversaries', 'Celebrate an unforgettable proposal, honeymoon, birthday, or anniversary on your own private yacht in Dubai Marina—complete with floral table styling, celebration cake, and skyline views.', '2 hours', 1250.0, NULL, 4.9, 207, '/uploads/activities/private-yacht-dinner-couples-cover.webp', '["/uploads/activities/private-yacht-dinner-couples-cover.webp","/uploads/activities/gallery-cruise-1.webp","/uploads/activities/gallery-cruise-2.webp","/uploads/activities/gallery-cruise-3.webp","/uploads/activities/gallery-cruise-4.webp","/uploads/activities/gallery-cruise-5.webp","/uploads/activities/gallery-cruise-6.webp"]', '[]', '["Private 2-hour luxury motor yacht charter with licensed captain & crew","Romantic candlelit table setup with rose petals & floral centerpiece","3-course dinner for two, sparkling non-alcoholic toast & celebration cake","Private Bluetooth sound system & Marina/JBR/Burj Al Arab lagoon route"]', '["Custom balloon arch / marquee \'MARRY ME\' letters (available on WhatsApp)","Professional onboard photographer add-on"]', 'Dubai Marina Yacht Club / Dubai Harbour Gate P — flexible sunset (05:30 PM) or night (08:00 PM) departure.', 'Daily', '[{"q":"How do I confirm my booking for Private Yacht Dinner (Couples)?","a":"Click \'Book on WhatsApp\' or submit the enquiry form below. Our UAE team replies within minutes on WhatsApp (+971 52 537 6838) with instant confirmation."},{"q":"Is hotel pick-up available?","a":"Hotel pick-up is included on most safari and sightseeing tours, and can be added to any cruise, watersport, or attraction ticket on WhatsApp."},{"q":"What is the cancellation policy?","a":"Free reschedule or cancellation up to 48 hours prior."}]', 1, 0, 4, 1, 'Private Yacht Dinner (Couples) | Book Online & WhatsApp — Anchor Point UAE', 'Private table, decorated setup, ideal for proposals and anniversaries. Duration: 2 hours. From AED 1250 per person. Instant confirmation on WhatsApp.', '2026-11-02 09:52:01', '2026-11-02 09:52:01', '2 hours, private yacht charter', 1, 0.0, 'Private couple charter (2 guests included; custom celebration add-ons available)', '{"overview":"Celebrate an unforgettable proposal, honeymoon, birthday, or anniversary on your own private yacht in Dubai Marina—complete with floral table styling, celebration cake, and skyline views.","boarding_point":"Dubai Marina Yacht Club / Dubai Harbour Gate P — flexible sunset (05:30 PM) or night (08:00 PM) departure.","menu_highlights":"Choice of grilled seafood, steak & chicken continental menu or vegetarian gourmet menu, celebration cake, fresh juices, soft drinks & water.","seating_options":"100% private aft dining deck, sunbed bow lounge & air-conditioned cabin.","entertainment":"Custom playlist via onboard Bose sound system; optional live violinist on request.","dress_code":"Smart casual / evening celebration attire (barefoot or clean soft deck shoes onboard).","cancellation":"Free reschedule or cancellation up to 48 hours prior.","reviews":[{"author":"David & Chloe (UK)","rating":5,"comment":"Proposed in front of the lit Marina skyline—the crew set up flowers and cake flawlessly!"}]}');
INSERT INTO `tours` (`id`, `category_id`, `title`, `slug`, `badge`, `short_desc`, `long_desc`, `duration`, `price_aed`, `original_price_aed`, `rating`, `reviews_count`, `featured_image`, `gallery_json`, `itinerary_json`, `inclusions_json`, `exclusions_json`, `pickup_details`, `availability`, `faq_json`, `is_featured`, `is_combo`, `sort_order`, `is_active`, `seo_title`, `seo_desc`, `created_at`, `updated_at`, `pickup_line`, `has_pickup`, `child_price_aed`, `age_policy`, `details_json`) VALUES (17, 3, 'Family Dinner Cruise', 'family-dinner-cruise', '', 'Kid-friendly menu and entertainment', 'An early, relaxed evening cruise designed with families in mind—featuring stroller-accessible boarding, high chairs, kid-loved menu favourites alongside Arabic & continental dishes, and lively family entertainment.', '2 hours', 120.0, NULL, 4.9, 214, '/uploads/activities/family-dinner-cruise-cover.webp', '["/uploads/activities/family-dinner-cruise-cover.webp","/uploads/activities/gallery-cruise-1.webp","/uploads/activities/gallery-cruise-2.webp","/uploads/activities/gallery-cruise-3.webp","/uploads/activities/gallery-cruise-4.webp","/uploads/activities/gallery-cruise-5.webp","/uploads/activities/gallery-cruise-6.webp"]', '[]', '["2-hour calm-water evening dinner cruise","Dedicated kid-friendly buffet corner alongside full international adult buffet","Unlimited juices, water, tea & soft drinks","Family-friendly magic/puppet segment & colorful Tanoura show"]', '["Optional hotel transfer","Birthday cake customization (ask on WhatsApp)"]', 'Dubai Creek / Dubai Marina family berth — boarding 07:30 PM, sailing 08:00 PM – 10:00 PM.', 'Daily', '[{"q":"How do I confirm my booking for Family Dinner Cruise?","a":"Click \'Book on WhatsApp\' or submit the enquiry form below. Our UAE team replies within minutes on WhatsApp (+971 52 537 6838) with instant confirmation."},{"q":"Is hotel pick-up available?","a":"Hotel pick-up is included on most safari and sightseeing tours, and can be added to any cruise, watersport, or attraction ticket on WhatsApp."},{"q":"What is the cancellation policy?","a":"Free cancellation up to 24 hours before sailing."}]', 0, 0, 5, 0, 'Family Dinner Cruise | Book Online & WhatsApp — Anchor Point UAE', 'Kid-friendly menu and entertainment. Duration: 2 hours. From AED 120 per person. Instant confirmation on WhatsApp.', '2026-11-02 09:52:01', '2026-11-02 09:52:01', '2 hours, optional hotel pick-up', 1, 75.0, 'Adults 12+ yrs | Children 3–11 yrs | Infants under 3 free (stroller-friendly)', '{"overview":"An early, relaxed evening cruise designed with families in mind—featuring stroller-accessible boarding, high chairs, kid-loved menu favourites alongside Arabic & continental dishes, and lively family entertainment.","boarding_point":"Dubai Creek / Dubai Marina family berth — boarding 07:30 PM, sailing 08:00 PM – 10:00 PM.","menu_highlights":"Kids\' mini-sliders, pasta, crispy chicken strips & cupcakes; Adult Arabic mezze, BBQ grills, curries, salads & desserts.","seating_options":"Enclosed air-conditioned family dining deck or railing-protected upper deck.","entertainment":"Tanoura spinning show & family interactive entertainment.","dress_code":"Casual family wear.","cancellation":"Free cancellation up to 24 hours before sailing.","reviews":[{"author":"Fatima N. (Kuwait)","rating":5,"comment":"Kids loved the Tanoura lights and mini pasta bar while we enjoyed the calm skyline views."}]}');
INSERT INTO `tours` (`id`, `category_id`, `title`, `slug`, `badge`, `short_desc`, `long_desc`, `duration`, `price_aed`, `original_price_aed`, `rating`, `reviews_count`, `featured_image`, `gallery_json`, `itinerary_json`, `inclusions_json`, `exclusions_json`, `pickup_details`, `availability`, `faq_json`, `is_featured`, `is_combo`, `sort_order`, `is_active`, `seo_title`, `seo_desc`, `created_at`, `updated_at`, `pickup_line`, `has_pickup`, `child_price_aed`, `age_policy`, `details_json`) VALUES (18, 3, 'Corporate and Group Cruise', 'corporate-and-group-cruise', '', 'Private booking for 20 or more guests', 'Host corporate gala dinners, team offsites, wedding welcome nights, or milestone group celebrations aboard a privately chartered glass boat, traditional dhow, or mega-yacht for 20 to 150+ guests.', '3 hours', 165.0, NULL, 4.9, 221, '/uploads/activities/corporate-and-group-cruise-cover.webp', '["/uploads/activities/corporate-and-group-cruise-cover.webp","/uploads/activities/gallery-cruise-1.webp","/uploads/activities/gallery-cruise-2.webp","/uploads/activities/gallery-cruise-3.webp","/uploads/activities/gallery-cruise-4.webp","/uploads/activities/gallery-cruise-5.webp","/uploads/activities/gallery-cruise-6.webp"]', '[]', '["Exclusive 3-hour private vessel charter in Dubai Marina or Creek","Custom banquet buffet dinner, welcome mocktails & unlimited soft drinks","PA microphone, projector/screen & background music/DJ setup","Dedicated onboard event coordinator"]', '["Group coach hotel transfers (available on request)","Custom corporate branding banners & floral styling"]', 'Dubai Marina or Dubai Harbour group pier — arrival 30 minutes prior to custom charter slot.', 'Daily', '[{"q":"How do I confirm my booking for Corporate and Group Cruise?","a":"Click \'Book on WhatsApp\' or submit the enquiry form below. Our UAE team replies within minutes on WhatsApp (+971 52 537 6838) with instant confirmation."},{"q":"Is hotel pick-up available?","a":"Hotel pick-up is included on most safari and sightseeing tours, and can be added to any cruise, watersport, or attraction ticket on WhatsApp."},{"q":"What is the cancellation policy?","a":"Flexible group terms confirmed on booking agreement."}]', 0, 0, 6, 0, 'Corporate and Group Cruise | Book Online & WhatsApp — Anchor Point UAE', 'Private booking for 20 or more guests. Duration: 3 hours. From AED 165 per person. Instant confirmation on WhatsApp.', '2026-11-02 09:52:01', '2026-11-02 09:52:01', '3 hours, private group charter', 1, 120.0, 'Group rate per guest (Minimum 20 guests; vessels available up to 150 guests)', '{"overview":"Host corporate gala dinners, team offsites, wedding welcome nights, or milestone group celebrations aboard a privately chartered glass boat, traditional dhow, or mega-yacht for 20 to 150+ guests.","boarding_point":"Dubai Marina or Dubai Harbour group pier — arrival 30 minutes prior to custom charter slot.","menu_highlights":"Tailored 4-star or 5-star international buffet (vegetarian, halal grilled meats, seafood, live stations & desserts).","seating_options":"Full dual-deck exclusive use (indoor banquet lower deck + open-air upper lounge deck).","entertainment":"PA system for speeches, background DJ/music, and optional Tanoura or live musicians.","dress_code":"Business casual or festive event attire.","cancellation":"Flexible group terms confirmed on booking agreement.","reviews":[{"author":"Stefan M. (Corporate Event, 45 pax)","rating":5,"comment":"Seamless charter for our regional sales summit—great food, mic setup, and Marina views."}]}');
INSERT INTO `tours` (`id`, `category_id`, `title`, `slug`, `badge`, `short_desc`, `long_desc`, `duration`, `price_aed`, `original_price_aed`, `rating`, `reviews_count`, `featured_image`, `gallery_json`, `itinerary_json`, `inclusions_json`, `exclusions_json`, `pickup_details`, `availability`, `faq_json`, `is_featured`, `is_combo`, `sort_order`, `is_active`, `seo_title`, `seo_desc`, `created_at`, `updated_at`, `pickup_line`, `has_pickup`, `child_price_aed`, `age_policy`, `details_json`) VALUES (19, 4, 'Jet Ski Ride', 'jet-ski-ride', '', 'Ride past Burj Al Arab and Palm Jumeirah with a guide', 'Ride modern Yamaha jet skis across turquoise Arabian Gulf waters with a certified lead instructor—framing views of Dubai Marina, JBR, Burj Al Arab, and Palm Jumeirah.', '30 to 60 minutes', 280.0, NULL, 4.9, 228, '/uploads/activities/jet-ski-ride-cover.webp', '["/uploads/activities/jet-ski-ride-cover.webp","/uploads/activities/gallery-water-1.webp","/uploads/activities/gallery-water-2.webp","/uploads/activities/gallery-water-3.webp","/uploads/activities/gallery-water-4.webp","/uploads/activities/gallery-water-5.webp","/uploads/activities/gallery-water-6.webp"]', '[]', '["Latest high-powered Yamaha VX/FX jet ski","Certified watersports safety briefing & lead guide on separate jet ski","Coastguard-approved life jackets, waterproof phone pouch & lockers","Complimentary action photos & short video clips taken by guide"]', '["Hotel transfers (optional private transfer on request)","Towels & swimwear"]', 'Umm Suqeim Fishing Harbour / Jumeirah Beach Marina (15 mins from Dubai Marina & Downtown). Exact pin shared on WhatsApp.', 'Daily', '[{"q":"How do I confirm my booking for Jet Ski Ride?","a":"Click \'Book on WhatsApp\' or submit the enquiry form below. Our UAE team replies within minutes on WhatsApp (+971 52 537 6838) with instant confirmation."},{"q":"Is hotel pick-up available?","a":"This experience starts at the venue/marina with instant ticket confirmation, and private hotel transfers can be added anytime on WhatsApp."},{"q":"What is the cancellation policy?","a":"100% free rescheduling or full refund if UAE Coastguard restricts sea access due to wind/waves."}]', 1, 0, 1, 1, 'Jet Ski Ride | Book Online & WhatsApp — Anchor Point UAE', 'Ride past Burj Al Arab and Palm Jumeirah with a guide. Duration: 30 to 60 minutes. From AED 280 per person. Instant confirmation on WhatsApp.', '2026-11-02 09:52:01', '2026-11-02 09:52:01', '30 to 60 minutes, Marina beach start', 0, 0.0, 'Minimum driver age 16+ yrs | Passenger 8+ yrs (Up to 2 riders per jet ski)', '{"overview":"Ride modern Yamaha jet skis across turquoise Arabian Gulf waters with a certified lead instructor—framing views of Dubai Marina, JBR, Burj Al Arab, and Palm Jumeirah.","start_location":"Umm Suqeim Fishing Harbour / Jumeirah Beach Marina (15 mins from Dubai Marina & Downtown). Exact pin shared on WhatsApp.","safety_requirements":"Minimum age 16 to drive, 8 to ride as passenger. Combined weight max 180 kg per jet ski. Basic water confidence required; life jackets mandatory. Valid passport/Emirates ID required by UAE Coastguard.","what_to_bring":"Original Passport or Emirates ID, swimwear, towel, Reef-safe sunscreen & sunglasses strap.","weather_policy":"100% free rescheduling or full refund if UAE Coastguard restricts sea access due to wind/waves.","package_discounts":"Combo Deal: Add a 15-minute Parasailing flight and save 15% when booked together on WhatsApp.","reviews":[{"author":"Kevin O. (Ireland)","rating":5,"comment":"Brand-new fast jet skis and our guide took awesome GoPro photos in front of Burj Al Arab for free!"}]}');
INSERT INTO `tours` (`id`, `category_id`, `title`, `slug`, `badge`, `short_desc`, `long_desc`, `duration`, `price_aed`, `original_price_aed`, `rating`, `reviews_count`, `featured_image`, `gallery_json`, `itinerary_json`, `inclusions_json`, `exclusions_json`, `pickup_details`, `availability`, `faq_json`, `is_featured`, `is_combo`, `sort_order`, `is_active`, `seo_title`, `seo_desc`, `created_at`, `updated_at`, `pickup_line`, `has_pickup`, `child_price_aed`, `age_policy`, `details_json`) VALUES (20, 4, 'Jet Ski Tour (Burj Al Arab)', 'jet-ski-tour-burj-al-arab', '', 'Guided route with photo stops', 'Our most popular 1-hour guided jet ski safari cruises directly out to the iconic sail-shaped Burj Al Arab and along the royal beaches towards Palm Jumeirah with dedicated photo stops on the water.', '1 hour', 390.0, NULL, 4.9, 95, '/uploads/activities/jet-ski-tour-burj-al-arab-cover.webp', '["/uploads/activities/jet-ski-tour-burj-al-arab-cover.webp","/uploads/activities/gallery-water-1.webp","/uploads/activities/gallery-water-2.webp","/uploads/activities/gallery-water-3.webp","/uploads/activities/gallery-water-4.webp","/uploads/activities/gallery-water-5.webp","/uploads/activities/gallery-water-6.webp"]', '[]', '["60-minute guided coastal jet ski tour to Burj Al Arab & Palm Jumeirah","Certified instructor, safety briefing & life jackets","Dedicated water-level photo & video stops at Burj Al Arab","Bottled water, showers & locker access"]', '["Hotel pick-up & drop-off","Swimwear & towels"]', 'Umm Suqeim Marina Berth 4, Jumeirah, Dubai (Arrive 20 minutes prior).', 'Daily', '[{"q":"How do I confirm my booking for Jet Ski Tour (Burj Al Arab)?","a":"Click \'Book on WhatsApp\' or submit the enquiry form below. Our UAE team replies within minutes on WhatsApp (+971 52 537 6838) with instant confirmation."},{"q":"Is hotel pick-up available?","a":"This experience starts at the venue/marina with instant ticket confirmation, and private hotel transfers can be added anytime on WhatsApp."},{"q":"What is the cancellation policy?","a":"Free rescheduling to any open slot or full refund in case of rough sea conditions."}]', 1, 0, 2, 1, 'Jet Ski Tour (Burj Al Arab) | Book Online & WhatsApp — Anchor Point UAE', 'Guided route with photo stops. Duration: 1 hour. From AED 390 per person. Instant confirmation on WhatsApp.', '2026-11-02 09:52:01', '2026-11-02 09:52:01', '1 hour, guided coastal route', 0, 0.0, 'Driver 16+ yrs | Passenger 8+ yrs (Price per jet ski for 1 or 2 riders)', '{"overview":"Our most popular 1-hour guided jet ski safari cruises directly out to the iconic sail-shaped Burj Al Arab and along the royal beaches towards Palm Jumeirah with dedicated photo stops on the water.","start_location":"Umm Suqeim Marina Berth 4, Jumeirah, Dubai (Arrive 20 minutes prior).","safety_requirements":"Original ID/Passport mandatory. Driver min 16 yrs; max 180 kg combined weight. Not suitable for pregnant guests.","what_to_bring":"Passport/ID, swimwear, towel & sunscreen.","weather_policy":"Free rescheduling to any open slot or full refund in case of rough sea conditions.","package_discounts":"Group of 3+ jet skis receives 10% combo discount via WhatsApp.","reviews":[{"author":"Matteo F. (Italy)","rating":5,"comment":"Seeing Burj Al Arab right from the water on a 1-hour jet ski tour was unforgettable."}]}');
INSERT INTO `tours` (`id`, `category_id`, `title`, `slug`, `badge`, `short_desc`, `long_desc`, `duration`, `price_aed`, `original_price_aed`, `rating`, `reviews_count`, `featured_image`, `gallery_json`, `itinerary_json`, `inclusions_json`, `exclusions_json`, `pickup_details`, `availability`, `faq_json`, `is_featured`, `is_combo`, `sort_order`, `is_active`, `seo_title`, `seo_desc`, `created_at`, `updated_at`, `pickup_line`, `has_pickup`, `child_price_aed`, `age_policy`, `details_json`) VALUES (21, 4, 'Parasailing', 'parasailing', '', 'Fly above the Palm and Dubai Marina coast', 'Soar peacefully up to 150 meters above the turquoise waters of JBR and Palm Jumeirah with dry winch-boat launch and landing—giving bird\'s-eye views of Dubai Marina\'s skyscrapers.', '15 minutes', 250.0, NULL, 4.9, 102, '/uploads/activities/parasailing-cover.webp', '["/uploads/activities/parasailing-cover.webp","/uploads/activities/gallery-water-1.webp","/uploads/activities/gallery-water-2.webp","/uploads/activities/gallery-water-3.webp","/uploads/activities/gallery-water-4.webp","/uploads/activities/gallery-water-5.webp","/uploads/activities/gallery-water-6.webp"]', '[]', '["Winch-boat cruise off JBR & Dubai Marina","12–15 minute parasailing flight up to 150 meters above the sea","Dry take-off and landing directly on the boat deck","Harness, life jacket & experienced captain/crew"]', '["GoPro flight video & photo package (optional extra)","Hotel transfers"]', 'Dubai Marina / JBR Beach Watersports Pontoon.', 'Daily', '[{"q":"How do I confirm my booking for Parasailing?","a":"Click \'Book on WhatsApp\' or submit the enquiry form below. Our UAE team replies within minutes on WhatsApp (+971 52 537 6838) with instant confirmation."},{"q":"Is hotel pick-up available?","a":"This experience starts at the venue/marina with instant ticket confirmation, and private hotel transfers can be added anytime on WhatsApp."},{"q":"What is the cancellation policy?","a":"Flights depend on steady wind; free instant rescheduling or refund if wind exceeds safety limits."}]', 1, 0, 3, 1, 'Parasailing | Book Online & WhatsApp — Anchor Point UAE', 'Fly above the Palm and Dubai Marina coast. Duration: 15 minutes. From AED 250 per person. Instant confirmation on WhatsApp.', '2026-11-02 09:52:01', '2026-11-02 09:52:01', '15 min flight (1 hr boat trip)', 0, 220.0, 'Minimum age 6+ yrs (Children under 12 fly tandem with adult)', '{"overview":"Soar peacefully up to 150 meters above the turquoise waters of JBR and Palm Jumeirah with dry winch-boat launch and landing—giving bird\'s-eye views of Dubai Marina\'s skyscrapers.","start_location":"Dubai Marina / JBR Beach Watersports Pontoon.","safety_requirements":"Single or tandem flights subject to wind; total harness weight 45 kg min – 180 kg max. No swimming skill required (dry boat landing).","what_to_bring":"Comfortable beachwear/shorts, towel, sunscreen & ID.","weather_policy":"Flights depend on steady wind; free instant rescheduling or refund if wind exceeds safety limits.","package_discounts":"Jet Ski + Parasailing Combo from AED 475 per person on WhatsApp.","reviews":[{"author":"Aisha R. (Bahrain)","rating":5,"comment":"Super smooth take-off and landing without even getting wet—amazing view of the Palm!"}]}');
INSERT INTO `tours` (`id`, `category_id`, `title`, `slug`, `badge`, `short_desc`, `long_desc`, `duration`, `price_aed`, `original_price_aed`, `rating`, `reviews_count`, `featured_image`, `gallery_json`, `itinerary_json`, `inclusions_json`, `exclusions_json`, `pickup_details`, `availability`, `faq_json`, `is_featured`, `is_combo`, `sort_order`, `is_active`, `seo_title`, `seo_desc`, `created_at`, `updated_at`, `pickup_line`, `has_pickup`, `child_price_aed`, `age_policy`, `details_json`) VALUES (22, 4, 'Flyboarding', 'flyboarding', '', 'Water-jet powered flight above the sea', 'Rise above the sea on twin hydro-thrust jets with one-on-one coaching from a certified Dubai flyboard instructor—most beginners stand and hover within their first 5 minutes!', '30 minutes', 340.0, NULL, 4.9, 109, '/uploads/activities/flyboarding-cover.webp', '["/uploads/activities/flyboarding-cover.webp","/uploads/activities/gallery-water-1.webp","/uploads/activities/gallery-water-2.webp","/uploads/activities/gallery-water-3.webp","/uploads/activities/gallery-water-4.webp","/uploads/activities/gallery-water-5.webp","/uploads/activities/gallery-water-6.webp"]', '[]', '["30-minute session (10-min briefing + 20-min water-jet flight)","1-on-1 certified flyboard instructor controlling thrust","Flyboard boots, helmet, impact vest & life jacket","Shower & locker access"]', '["Professional action photography/video","Hotel transfers"]', 'Jumeirah / Dubai Marina Watersports Centre.', 'Daily', '[{"q":"How do I confirm my booking for Flyboarding?","a":"Click \'Book on WhatsApp\' or submit the enquiry form below. Our UAE team replies within minutes on WhatsApp (+971 52 537 6838) with instant confirmation."},{"q":"Is hotel pick-up available?","a":"This experience starts at the venue/marina with instant ticket confirmation, and private hotel transfers can be added anytime on WhatsApp."},{"q":"What is the cancellation policy?","a":"Free rescheduling if sea state is choppy."}]', 1, 0, 4, 1, 'Flyboarding | Book Online & WhatsApp — Anchor Point UAE', 'Water-jet powered flight above the sea. Duration: 30 minutes. From AED 340 per person. Instant confirmation on WhatsApp.', '2026-11-02 09:52:01', '2026-11-02 09:52:01', '30 minutes, 1-on-1 instructor', 0, 0.0, 'Minimum age 16+ yrs', '{"overview":"Rise above the sea on twin hydro-thrust jets with one-on-one coaching from a certified Dubai flyboard instructor—most beginners stand and hover within their first 5 minutes!","start_location":"Jumeirah / Dubai Marina Watersports Centre.","safety_requirements":"Min age 16 yrs; weight 45 kg – 115 kg; must be comfortable swimming in deep water with a vest.","what_to_bring":"Swimwear, towel, sunscreen & ID.","weather_policy":"Free rescheduling if sea state is choppy.","package_discounts":"Combine Flyboarding + 30-min Jet Ski and save AED 60.","reviews":[{"author":"Lucas B. (Netherlands)","rating":5,"comment":"Easier than it looks! Instructor got me flying 4 meters up within minutes."}]}');
INSERT INTO `tours` (`id`, `category_id`, `title`, `slug`, `badge`, `short_desc`, `long_desc`, `duration`, `price_aed`, `original_price_aed`, `rating`, `reviews_count`, `featured_image`, `gallery_json`, `itinerary_json`, `inclusions_json`, `exclusions_json`, `pickup_details`, `availability`, `faq_json`, `is_featured`, `is_combo`, `sort_order`, `is_active`, `seo_title`, `seo_desc`, `created_at`, `updated_at`, `pickup_line`, `has_pickup`, `child_price_aed`, `age_policy`, `details_json`) VALUES (23, 4, 'Banana Boat and Donut Ride', 'banana-boat-and-donut-ride', '', 'Fun group rides for families and friends', 'Laugh-out-loud inflatable water rides towed by speedboat off JBR and Dubai Marina—perfect for families, teens, and groups of friends.', '15 to 30 minutes', 110.0, NULL, 4.9, 116, '/uploads/activities/banana-boat-and-donut-ride-cover.webp', '["/uploads/activities/banana-boat-and-donut-ride-cover.webp","/uploads/activities/gallery-water-1.webp","/uploads/activities/gallery-water-2.webp","/uploads/activities/gallery-water-3.webp","/uploads/activities/gallery-water-4.webp","/uploads/activities/gallery-water-5.webp","/uploads/activities/gallery-water-6.webp"]', '[]', '["High-energy speedboat tow on inflatable Banana Boat or spinning Donut tube","Life jackets & safety briefing","Speed adjusted to family-mild or thrill-splash level"]', '["Photos & videos","Hotel transfers & towels"]', 'JBR Beach / Marina Watersports Kiosk.', 'Daily', '[{"q":"How do I confirm my booking for Banana Boat and Donut Ride?","a":"Click \'Book on WhatsApp\' or submit the enquiry form below. Our UAE team replies within minutes on WhatsApp (+971 52 537 6838) with instant confirmation."},{"q":"Is hotel pick-up available?","a":"This experience starts at the venue/marina with instant ticket confirmation, and private hotel transfers can be added anytime on WhatsApp."},{"q":"What is the cancellation policy?","a":"Free rescheduling in case of rough waves."}]', 0, 0, 5, 1, 'Banana Boat and Donut Ride | Book Online & WhatsApp — Anchor Point UAE', 'Fun group rides for families and friends. Duration: 15 to 30 minutes. From AED 110 per person. Instant confirmation on WhatsApp.', '2026-11-02 09:52:01', '2026-11-02 09:52:01', '15 to 30 minutes, JBR beach start', 0, 95.0, 'Minimum age 6+ yrs (Minimum 2 riders)', '{"overview":"Laugh-out-loud inflatable water rides towed by speedboat off JBR and Dubai Marina—perfect for families, teens, and groups of friends.","start_location":"JBR Beach / Marina Watersports Kiosk.","safety_requirements":"Min age 6 yrs accompanied by adult; life jackets provided and worn at all times.","what_to_bring":"Swimwear, towel & change of clothes.","weather_policy":"Free rescheduling in case of rough waves.","package_discounts":"Book both Banana Boat + Donut Ride back-to-back (30 mins total) for AED 175/person.","reviews":[{"author":"Samira K. (Jordan)","rating":5,"comment":"Our teenagers couldn\'t stop laughing on the donut ride! Safe and super fun."}]}');
INSERT INTO `tours` (`id`, `category_id`, `title`, `slug`, `badge`, `short_desc`, `long_desc`, `duration`, `price_aed`, `original_price_aed`, `rating`, `reviews_count`, `featured_image`, `gallery_json`, `itinerary_json`, `inclusions_json`, `exclusions_json`, `pickup_details`, `availability`, `faq_json`, `is_featured`, `is_combo`, `sort_order`, `is_active`, `seo_title`, `seo_desc`, `created_at`, `updated_at`, `pickup_line`, `has_pickup`, `child_price_aed`, `age_policy`, `details_json`) VALUES (24, 4, 'Speed Boat Tour', 'speed-boat-tour', '', 'Fast boat ride along the coast and Atlantis', 'Zip out of Dubai Marina canal into the open Arabian Gulf on a rigid-inflatable speedboat—stopping for postcard water-level photos at Ain Dubai, Atlantis The Palm, and Burj Al Arab.', '1 hour', 160.0, NULL, 4.9, 123, '/uploads/activities/speed-boat-tour-cover.webp', '["/uploads/activities/speed-boat-tour-cover.webp","/uploads/activities/gallery-water-1.webp","/uploads/activities/gallery-water-2.webp","/uploads/activities/gallery-water-3.webp","/uploads/activities/gallery-water-4.webp","/uploads/activities/gallery-water-5.webp","/uploads/activities/gallery-water-6.webp"]', '[]', '["60–90 min high-speed RIB sightseeing boat ride from Dubai Marina","Photo stops at Ain Dubai, JBR, Atlantis The Palm & Burj Al Arab","Life jackets, live captain commentary & chilled bottled water"]', '["Hotel transfers","Souvenir photo prints"]', 'Dubai Marina Walk Berth (next to Marina Gate / Pier 7).', 'Daily', '[{"q":"How do I confirm my booking for Speed Boat Tour?","a":"Click \'Book on WhatsApp\' or submit the enquiry form below. Our UAE team replies within minutes on WhatsApp (+971 52 537 6838) with instant confirmation."},{"q":"Is hotel pick-up available?","a":"This experience starts at the venue/marina with instant ticket confirmation, and private hotel transfers can be added anytime on WhatsApp."},{"q":"What is the cancellation policy?","a":"Free date/time change or full refund if sea conditions cancel departure."}]', 0, 0, 6, 1, 'Speed Boat Tour | Book Online & WhatsApp — Anchor Point UAE', 'Fast boat ride along the coast and Atlantis. Duration: 1 hour. From AED 160 per person. Instant confirmation on WhatsApp.', '2026-11-02 09:52:01', '2026-11-02 09:52:01', '1 hour, Dubai Marina pier', 0, 120.0, 'Adults 12+ yrs | Children 5–11 yrs (Minimum age 5 yrs / 15 kg)', '{"overview":"Zip out of Dubai Marina canal into the open Arabian Gulf on a rigid-inflatable speedboat—stopping for postcard water-level photos at Ain Dubai, Atlantis The Palm, and Burj Al Arab.","start_location":"Dubai Marina Walk Berth (next to Marina Gate / Pier 7).","safety_requirements":"Minimum child weight 15 kg (5+ yrs). Not permitted for pregnant guests or guests with back injuries.","what_to_bring":"Casual clothes, sunglasses, sunscreen & camera/phone.","weather_policy":"Free date/time change or full refund if sea conditions cancel departure.","package_discounts":"Family of 4 saves 10% on morning departures.","reviews":[{"author":"Oliver S. (Germany)","rating":5,"comment":"Thrilling ride and the best angles of Atlantis and Burj Al Arab from the sea."}]}');
INSERT INTO `tours` (`id`, `category_id`, `title`, `slug`, `badge`, `short_desc`, `long_desc`, `duration`, `price_aed`, `original_price_aed`, `rating`, `reviews_count`, `featured_image`, `gallery_json`, `itinerary_json`, `inclusions_json`, `exclusions_json`, `pickup_details`, `availability`, `faq_json`, `is_featured`, `is_combo`, `sort_order`, `is_active`, `seo_title`, `seo_desc`, `created_at`, `updated_at`, `pickup_line`, `has_pickup`, `child_price_aed`, `age_policy`, `details_json`) VALUES (25, 4, 'Scuba Diving (Beginners)', 'scuba-diving-beginners', '', 'Training and a guided dive', 'Try scuba diving in warm Arabian Gulf waters with zero prior experience needed. A PADI-certified instructor teaches you basic breathing and hand signals in shallow water before guiding you slowly past colourful reef fish.', '2 to 3 hours', 350.0, NULL, 4.9, 130, '/uploads/activities/scuba-diving-beginners-cover.webp', '["/uploads/activities/scuba-diving-beginners-cover.webp","/uploads/activities/gallery-water-1.webp","/uploads/activities/gallery-water-2.webp","/uploads/activities/gallery-water-3.webp","/uploads/activities/gallery-water-4.webp","/uploads/activities/gallery-water-5.webp","/uploads/activities/gallery-water-6.webp"]', '[]', '["PADI Discover Scuba safety & shallow-water breathing briefing","Full scuba gear (wetsuit, mask, fins, BCD, regulator & tank)","45-minute guided underwater reef dive (up to 10–12m max) with instructor","Complimentary underwater photos & video"]', '["Hotel transfers","Certification card (full PADI course available on request)"]', 'Jumeirah 3 Dive Beach Centre, Dubai.', 'Daily', '[{"q":"How do I confirm my booking for Scuba Diving (Beginners)?","a":"Click \'Book on WhatsApp\' or submit the enquiry form below. Our UAE team replies within minutes on WhatsApp (+971 52 537 6838) with instant confirmation."},{"q":"Is hotel pick-up available?","a":"This experience starts at the venue/marina with instant ticket confirmation, and private hotel transfers can be added anytime on WhatsApp."},{"q":"What is the cancellation policy?","a":"Free rescheduling if underwater visibility or sea state is unsuitable."}]', 0, 0, 7, 1, 'Scuba Diving (Beginners) | Book Online & WhatsApp — Anchor Point UAE', 'Training and a guided dive. Duration: 2 to 3 hours. From AED 350 per person. Instant confirmation on WhatsApp.', '2026-11-02 09:52:01', '2026-11-02 09:52:01', '2 to 3 hours, equipment included', 0, 0.0, 'Minimum age 10+ yrs (No prior diving license required)', '{"overview":"Try scuba diving in warm Arabian Gulf waters with zero prior experience needed. A PADI-certified instructor teaches you basic breathing and hand signals in shallow water before guiding you slowly past colourful reef fish.","start_location":"Jumeirah 3 Dive Beach Centre, Dubai.","safety_requirements":"Min age 10 yrs. Do NOT fly on an airplane within 12–18 hours after scuba diving. Medical questionnaire completed before dive.","what_to_bring":"Swimwear, towel & Emirates ID / Passport.","weather_policy":"Free rescheduling if underwater visibility or sea state is unsuitable.","package_discounts":"Couples / 2+ divers pay AED 320 per person.","reviews":[{"author":"Mina P. (South Korea)","rating":5,"comment":"Patient instructors made my very first breath underwater calm and unforgettable—plus free underwater photos!"}]}');
INSERT INTO `tours` (`id`, `category_id`, `title`, `slug`, `badge`, `short_desc`, `long_desc`, `duration`, `price_aed`, `original_price_aed`, `rating`, `reviews_count`, `featured_image`, `gallery_json`, `itinerary_json`, `inclusions_json`, `exclusions_json`, `pickup_details`, `availability`, `faq_json`, `is_featured`, `is_combo`, `sort_order`, `is_active`, `seo_title`, `seo_desc`, `created_at`, `updated_at`, `pickup_line`, `has_pickup`, `child_price_aed`, `age_policy`, `details_json`) VALUES (26, 4, 'Fishing Trip', 'fishing-trip', '', 'Deep sea fishing with equipment and refreshments', 'Head offshore into productive Arabian Gulf fishing grounds targeting kingfish, barracuda, hammour, cobia, and sultan ibrahim aboard a fully equipped sport-fishing boat with captain and crew.', '4 hours', 320.0, NULL, 4.9, 137, '/uploads/activities/fishing-trip-cover.webp', '["/uploads/activities/fishing-trip-cover.webp","/uploads/activities/gallery-water-1.webp","/uploads/activities/gallery-water-2.webp","/uploads/activities/gallery-water-3.webp","/uploads/activities/gallery-water-4.webp","/uploads/activities/gallery-water-5.webp","/uploads/activities/gallery-water-6.webp"]', '[]', '["4-hour offshore deep-sea sport fishing charter from Dubai","Experienced captain, deckhand, sonar fish-finder & UAE fishing permit","All trolling & bottom-fishing rods, reels, tackle & bait","Ice box, chilled water & soft drinks (keep your catch!)"]', '["Onboard grilling (available on private 36ft+ charters)","Optional hotel transfer supplement on shared slots"]', 'Dubai Harbour / Umm Suqeim Fishing Marina — 06:00 AM morning or 02:00 PM afternoon departure.', 'Daily', '[{"q":"How do I confirm my booking for Fishing Trip?","a":"Click \'Book on WhatsApp\' or submit the enquiry form below. Our UAE team replies within minutes on WhatsApp (+971 52 537 6838) with instant confirmation."},{"q":"Is hotel pick-up available?","a":"Hotel pick-up is included on most safari and sightseeing tours, and can be added to any cruise, watersport, or attraction ticket on WhatsApp."},{"q":"What is the cancellation policy?","a":"100% free rescheduling or refund if Coastguard issues offshore wind warning."}]', 0, 0, 8, 1, 'Fishing Trip | Book Online & WhatsApp — Anchor Point UAE', 'Deep sea fishing with equipment and refreshments. Duration: 4 hours. From AED 320 per person. Instant confirmation on WhatsApp.', '2026-11-02 09:52:01', '2026-11-02 09:52:01', '4 hours, Dubai Marina harbour', 1, 250.0, 'Shared trip 10+ yrs | Private charter welcomes all ages', '{"overview":"Head offshore into productive Arabian Gulf fishing grounds targeting kingfish, barracuda, hammour, cobia, and sultan ibrahim aboard a fully equipped sport-fishing boat with captain and crew.","start_location":"Dubai Harbour / Umm Suqeim Fishing Marina — 06:00 AM morning or 02:00 PM afternoon departure.","safety_requirements":"Original Passport or Emirates ID required by Coastguard for all passengers; life jackets onboard.","what_to_bring":"Passport/ID, hat, sunglasses, sunscreen & light snacks.","weather_policy":"100% free rescheduling or refund if Coastguard issues offshore wind warning.","package_discounts":"Private 4-hour boat charter for up to 8 guests available at special group rate on WhatsApp.","reviews":[{"author":"Andrei V. (Romania)","rating":5,"comment":"Caught barracuda and kingfish! Crew knew the exact offshore spots and handled all bait and gear."}]}');
INSERT INTO `tours` (`id`, `category_id`, `title`, `slug`, `badge`, `short_desc`, `long_desc`, `duration`, `price_aed`, `original_price_aed`, `rating`, `reviews_count`, `featured_image`, `gallery_json`, `itinerary_json`, `inclusions_json`, `exclusions_json`, `pickup_details`, `availability`, `faq_json`, `is_featured`, `is_combo`, `sort_order`, `is_active`, `seo_title`, `seo_desc`, `created_at`, `updated_at`, `pickup_line`, `has_pickup`, `child_price_aed`, `age_policy`, `details_json`) VALUES (27, 5, 'Burj Khalifa (At the Top)', 'burj-khalifa-at-the-top', 'Landmark', 'Observation deck tickets, standard and prime hours', 'Ascend the world\'s tallest building in 60 seconds and step out onto the open-air terrace of Level 124 and Level 125 for sweeping 360-degree views across Downtown Dubai, the Arabian Gulf, and surrounding desert.', '1.5 to 2 hours', 179.0, NULL, 4.9, 144, '/uploads/activities/burj-khalifa-at-the-top-cover.webp', '["/uploads/activities/burj-khalifa-at-the-top-cover.webp","/uploads/activities/gallery-tickets-1.webp","/uploads/activities/gallery-tickets-2.webp","/uploads/activities/gallery-tickets-3.webp","/uploads/activities/gallery-tickets-4.webp","/uploads/activities/gallery-tickets-5.webp","/uploads/activities/gallery-tickets-6.webp"]', '[]', '["Official timed-entry QR ticket to Burj Khalifa Levels 124 & 125","High-speed 60-second double-deck elevator ride","Indoor 360° observation deck, outdoor terrace & viewing telescopes"]', '["Prime sunset slot supplement (04:00 PM – 06:30 PM) or Level 148 SKY upgrade","Hotel transfers unless requested on WhatsApp"]', 'Daily 07:00 AM – 12:00 Midnight (Last entry 11:15 PM).', 'Daily', '[{"q":"How do I confirm my booking for Burj Khalifa (At the Top)?","a":"Click \'Book on WhatsApp\' or submit the enquiry form below. Our UAE team replies within minutes on WhatsApp (+971 52 537 6838) with instant confirmation."},{"q":"Is hotel pick-up available?","a":"This experience starts at the venue/marina with instant ticket confirmation, and private hotel transfers can be added anytime on WhatsApp."},{"q":"What is the cancellation policy?","a":"Timed-entry tickets are valid for the selected date and slot; non-refundable once barcode is issued. Arrive at Dubai Mall Lower Ground entrance 20 minutes early."}]', 1, 0, 1, 1, 'Burj Khalifa (At the Top) | Book Online & WhatsApp — Anchor Point UAE', 'Observation deck tickets, standard and prime hours. Duration: 1.5 to 2 hours. From AED 179 per person. Instant confirmation on WhatsApp.', '2026-11-02 09:52:01', '2026-11-02 09:52:01', 'Landmark, timed-entry ticket', 0, 145.0, 'Adults 8+ yrs | Children 3–7 yrs | Infants under 3 free', '{"attraction_type":"Landmark","overview":"Ascend the world\'s tallest building in 60 seconds and step out onto the open-air terrace of Level 124 and Level 125 for sweeping 360-degree views across Downtown Dubai, the Arabian Gulf, and surrounding desert.","opening_hours":"Daily 07:00 AM – 12:00 Midnight (Last entry 11:15 PM).","ticket_types":[{"name":"Levels 124 & 125 — Non-Prime Hours","adult":"AED 179","child":"AED 145"},{"name":"Levels 124 & 125 — Prime Sunset Hours (16:00–18:30)","adult":"AED 259","child":"AED 165"},{"name":"Level 148 SKY VIP Fast-Track + Lounge","adult":"AED 399","child":"AED 399"}],"date_time_note":"Choose your preferred visit date and time window in the form below—exact entry slot is confirmed with you on WhatsApp before issuing.","delivery_method":"Official mobile QR PDF ticket sent directly to your WhatsApp and Email.","terms_rules":"Timed-entry tickets are valid for the selected date and slot; non-refundable once barcode is issued. Arrive at Dubai Mall Lower Ground entrance 20 minutes early.","reviews":[{"author":"Rachel T. (USA)","rating":5,"comment":"QR tickets arrived on WhatsApp in 5 minutes—scanned straight into the Burj Khalifa queue at Dubai Mall!"}]}');
INSERT INTO `tours` (`id`, `category_id`, `title`, `slug`, `badge`, `short_desc`, `long_desc`, `duration`, `price_aed`, `original_price_aed`, `rating`, `reviews_count`, `featured_image`, `gallery_json`, `itinerary_json`, `inclusions_json`, `exclusions_json`, `pickup_details`, `availability`, `faq_json`, `is_featured`, `is_combo`, `sort_order`, `is_active`, `seo_title`, `seo_desc`, `created_at`, `updated_at`, `pickup_line`, `has_pickup`, `child_price_aed`, `age_policy`, `details_json`) VALUES (28, 5, 'Dubai Frame', 'dubai-frame', 'Landmark', 'Skyline views from the glass-floor bridge', 'Stand 150 meters high on the 93-meter glass Sky Bridge of Dubai Frame—looking north over historic Deira and Dubai Creek, and south across the towering skyscrapers of Sheikh Zayed Road.', '1 to 1.5 hours', 55.0, NULL, 4.9, 151, '/uploads/activities/dubai-frame-cover.webp', '["/uploads/activities/dubai-frame-cover.webp","/uploads/activities/gallery-tickets-1.webp","/uploads/activities/gallery-tickets-2.webp","/uploads/activities/gallery-tickets-3.webp","/uploads/activities/gallery-tickets-4.webp","/uploads/activities/gallery-tickets-5.webp","/uploads/activities/gallery-tickets-6.webp"]', '[]', '["Official entry ticket to Dubai Frame in Zabeel Park","Old Dubai gallery, 150m-high Sky Deck & pressure-sensitive crystal glass walk","Future Dubai immersive vortex tunnel"]', '["Food & beverages on Sky Deck","Hotel transfers (optional on WhatsApp)"]', 'Daily 09:00 AM – 09:00 PM (Last entry 08:30 PM).', 'Daily', '[{"q":"How do I confirm my booking for Dubai Frame?","a":"Click \'Book on WhatsApp\' or submit the enquiry form below. Our UAE team replies within minutes on WhatsApp (+971 52 537 6838) with instant confirmation."},{"q":"Is hotel pick-up available?","a":"This experience starts at the venue/marina with instant ticket confirmation, and private hotel transfers can be added anytime on WhatsApp."},{"q":"What is the cancellation policy?","a":"Valid for single entry on selected date; non-refundable after issuance."}]', 1, 0, 2, 1, 'Dubai Frame | Book Online & WhatsApp — Anchor Point UAE', 'Skyline views from the glass-floor bridge. Duration: 1 to 1.5 hours. From AED 55 per person. Instant confirmation on WhatsApp.', '2026-11-02 09:52:01', '2026-11-02 09:52:01', 'Landmark, instant e-ticket', 0, 25.0, 'Adults 13+ yrs | Children 3–12 yrs | Under 3 & People of Determination free', '{"attraction_type":"Landmark","overview":"Stand 150 meters high on the 93-meter glass Sky Bridge of Dubai Frame—looking north over historic Deira and Dubai Creek, and south across the towering skyscrapers of Sheikh Zayed Road.","opening_hours":"Daily 09:00 AM – 09:00 PM (Last entry 08:30 PM).","ticket_types":[{"name":"Standard Entry Ticket (Adult 13+)","adult":"AED 55","child":"AED 25"}],"date_time_note":"Select your preferred visit date in the booking form; tickets allow flexible daytime or sunset entry.","delivery_method":"Instant PDF barcode ticket via WhatsApp & Email.","terms_rules":"Valid for single entry on selected date; non-refundable after issuance.","reviews":[{"author":"Hassan M. (Egypt)","rating":5,"comment":"Walking across the clear glass floor 150m up was thrilling! Quick ticket delivery on WhatsApp."}]}');
INSERT INTO `tours` (`id`, `category_id`, `title`, `slug`, `badge`, `short_desc`, `long_desc`, `duration`, `price_aed`, `original_price_aed`, `rating`, `reviews_count`, `featured_image`, `gallery_json`, `itinerary_json`, `inclusions_json`, `exclusions_json`, `pickup_details`, `availability`, `faq_json`, `is_featured`, `is_combo`, `sort_order`, `is_active`, `seo_title`, `seo_desc`, `created_at`, `updated_at`, `pickup_line`, `has_pickup`, `child_price_aed`, `age_policy`, `details_json`) VALUES (29, 5, 'Museum of the Future', 'museum-of-the-future', 'Museum', 'Timed-entry exhibitions', 'Step inside Dubai\'s architectural icon to experience interactive journeys to the year 2071—from orbital space stations and bio-engineered rainforest libraries to futuristic wellness and kids\' innovation labs.', '2 to 3 hours', 159.0, NULL, 4.9, 158, '/uploads/activities/museum-of-the-future-cover.webp', '["/uploads/activities/museum-of-the-future-cover.webp","/uploads/activities/gallery-tickets-1.webp","/uploads/activities/gallery-tickets-2.webp","/uploads/activities/gallery-tickets-3.webp","/uploads/activities/gallery-tickets-4.webp","/uploads/activities/gallery-tickets-5.webp","/uploads/activities/gallery-tickets-6.webp"]', '[]', '["Official timed-entry ticket (or Pioneer flexible-entry pass upgrade)","Access to OSS Hope Space Station, Heal Institute, Al Waha & Future Heroes floors","Outdoor viewing deck inside the calligraphy torus"]', '["Valet parking","Hotel transfers (available on request)"]', 'Daily 09:30 AM – 09:00 PM (Last entry 07:00 PM).', 'Daily', '[{"q":"How do I confirm my booking for Museum of the Future?","a":"Click \'Book on WhatsApp\' or submit the enquiry form below. Our UAE team replies within minutes on WhatsApp (+971 52 537 6838) with instant confirmation."},{"q":"Is hotel pick-up available?","a":"This experience starts at the venue/marina with instant ticket confirmation, and private hotel transfers can be added anytime on WhatsApp."},{"q":"What is the cancellation policy?","a":"Strictly valid for booked date/time slot; non-refundable once issued."}]', 1, 0, 3, 1, 'Museum of the Future | Book Online & WhatsApp — Anchor Point UAE', 'Timed-entry exhibitions. Duration: 2 to 3 hours. From AED 159 per person. Instant confirmation on WhatsApp.', '2026-11-02 09:52:01', '2026-11-02 09:52:01', 'Museum, timed-entry ticket', 0, 159.0, 'Ages 4+ require standard ticket | Children under 4 enter free', '{"attraction_type":"Museum","overview":"Step inside Dubai\'s architectural icon to experience interactive journeys to the year 2071—from orbital space stations and bio-engineered rainforest libraries to futuristic wellness and kids\' innovation labs.","opening_hours":"Daily 09:30 AM – 09:00 PM (Last entry 07:00 PM).","ticket_types":[{"name":"Timed-Entry Admission (Ages 4+)","adult":"AED 159","child":"AED 159"},{"name":"Pioneer Pass — Anytime Entry + AED 50 Shop Credit","adult":"AED 399","child":"AED 399"}],"date_time_note":"Museum of the Future slots sell out days ahead—pick your date in the form and our team confirms open times immediately on WhatsApp.","delivery_method":"Official QR e-ticket delivered on WhatsApp & Email.","terms_rules":"Strictly valid for booked date/time slot; non-refundable once issued.","reviews":[{"author":"Emily C. (Singapore)","rating":5,"comment":"Anchor Point secured morning slots for our family when everything looked tricky—incredible museum!"}]}');
INSERT INTO `tours` (`id`, `category_id`, `title`, `slug`, `badge`, `short_desc`, `long_desc`, `duration`, `price_aed`, `original_price_aed`, `rating`, `reviews_count`, `featured_image`, `gallery_json`, `itinerary_json`, `inclusions_json`, `exclusions_json`, `pickup_details`, `availability`, `faq_json`, `is_featured`, `is_combo`, `sort_order`, `is_active`, `seo_title`, `seo_desc`, `created_at`, `updated_at`, `pickup_line`, `has_pickup`, `child_price_aed`, `age_policy`, `details_json`) VALUES (30, 5, 'Dubai Aquarium and Underwater Zoo', 'dubai-aquarium-and-underwater-zoo', 'Family', 'Walk-through tunnel and zoo tickets', 'Walk through a 10-million-liter suspended aquarium tunnel surrounded by sand tiger sharks and giant stingrays inside Dubai Mall, then explore Rainforest, Rocky Shore, and King Croc habitats upstairs.', '2 hours', 169.0, NULL, 4.9, 165, '/uploads/activities/dubai-aquarium-and-underwater-zoo-cover.webp', '["/uploads/activities/dubai-aquarium-and-underwater-zoo-cover.webp","/uploads/activities/gallery-tickets-1.webp","/uploads/activities/gallery-tickets-2.webp","/uploads/activities/gallery-tickets-3.webp","/uploads/activities/gallery-tickets-4.webp","/uploads/activities/gallery-tickets-5.webp","/uploads/activities/gallery-tickets-6.webp"]', '[]', '["48-meter walk-through 270° Underwater Tunnel at Dubai Mall","Underwater Zoo (Level 2), King Croc encounter & Penguin Cove/Submersible simulator (package dependent)"]', '["Cage snorkeling / shark dive upgrades","Hotel transfers"]', 'Mon–Thu 10:00 AM – 10:15 PM | Fri–Sun 10:00 AM – 11:15 PM (Last entry 45 mins before close).', 'Daily', '[{"q":"How do I confirm my booking for Dubai Aquarium and Underwater Zoo?","a":"Click \'Book on WhatsApp\' or submit the enquiry form below. Our UAE team replies within minutes on WhatsApp (+971 52 537 6838) with instant confirmation."},{"q":"Is hotel pick-up available?","a":"This experience starts at the venue/marina with instant ticket confirmation, and private hotel transfers can be added anytime on WhatsApp."},{"q":"What is the cancellation policy?","a":"Single-day admission; non-refundable once barcode is generated."}]', 1, 0, 4, 1, 'Dubai Aquarium and Underwater Zoo | Book Online & WhatsApp — Anchor Point UAE', 'Walk-through tunnel and zoo tickets. Duration: 2 hours. From AED 169 per person. Instant confirmation on WhatsApp.', '2026-11-02 09:52:01', '2026-11-02 09:52:01', 'Family attraction, instant ticket', 0, 169.0, 'Ages 2+ yrs | Infants under 2 enter free', '{"attraction_type":"Family","overview":"Walk through a 10-million-liter suspended aquarium tunnel surrounded by sand tiger sharks and giant stingrays inside Dubai Mall, then explore Rainforest, Rocky Shore, and King Croc habitats upstairs.","opening_hours":"Mon–Thu 10:00 AM – 10:15 PM | Fri–Sun 10:00 AM – 11:15 PM (Last entry 45 mins before close).","ticket_types":[{"name":"Aquarium Tunnel + Underwater Zoo","adult":"AED 169","child":"AED 169"},{"name":"Ultimate Explorer Pass (Glass Boat + Penguin Cove)","adult":"AED 269","child":"AED 269"}],"date_time_note":"Choose your preferred visit date in the form; open daytime entry during mall hours.","delivery_method":"Instant QR e-ticket sent via WhatsApp & Email.","terms_rules":"Single-day admission; non-refundable once barcode is generated.","reviews":[{"author":"Zainab A. (Oman)","rating":5,"comment":"Must-do with kids inside Dubai Mall—seeing King Croc and sharks overhead was awesome."}]}');
