INSERT INTO `services` (`id`, `category_id`, `title`, `slug`, `badge`, `short_desc`, `content`, `featured_image`, `price_starting_aed`, `timeline`, `deliverables_json`, `requirements_json`, `faq_json`, `sort_order`, `is_featured`, `is_active`, `seo_title`, `seo_desc`, `created_at`) VALUES (1, 1, 'Dubai Mainland Company Formation', 'new-trade-license', '100% Foreign Ownership', 'Set up your commercial, professional, or industrial company in Dubai Mainland with 100% foreign ownership and zero corporate red tape.', '<p>Establishing a mainland company in Dubai under the Department of Economy and Tourism (DET) offers the freedom to trade directly within the UAE local market and globally without restrictions. With recent commercial law reforms, 100% foreign ownership is available across over 1,000 commercial and industrial activities.</p><h3>Why Choose Dubai Mainland?</h3><ul><li><strong>Direct UAE Market Access:</strong> Trade anywhere in the UAE and take on government and semi-government contracts.</li><li><strong>No Minimum Share Capital:</strong> Flexible capital structure for most business activities.</li><li><strong>Multiple Visa Allocation:</strong> Obtain as many employee residency visas as your office space allows.</li><li><strong>Prestigious Dubai Commercial Address:</strong> Establish offices anywhere in prime locations across Business Bay, Downtown, or Deira.</li></ul><p>Anchor Point manages the entire formation journey: initial approval, trade name reservation, drafting Memorandum of Association (MOA), Ejari office leasing assistance, and immediate issuance of your DED Commercial License.</p>', '/uploads/services/new-trade-license.jpg', 12500.0, '3–5 business days', '["Trade Name Reservation Certificate","Initial Approval Certificate","Notarized Memorandum of Association (MOA)","Dubai DET Commercial Trade License","Corporate Chamber of Commerce Certificate"]', '["Passport copy of shareholders & managers","UAE Residence Visa or Tourist Visa copy","3 proposed company trade names","Preferred business activity selection"]', '[{"q":"Can an expat own 100% of a Dubai Mainland company?","a":"Yes! Under UAE Commercial Companies Law, foreign investors can own 100% of mainland companies for most commercial, industrial, and trading activities without requiring an Emirati partner."},{"q":"How long does mainland trade license issuance take?","a":"With Anchor Point, initial approvals and trade name reservations are completed in 24 hours, and the final trade license is typically issued within 3 to 5 business days."}]', 1, 1, 1, 'Dubai Mainland Company Formation | DED License 100% Ownership', 'Start your Dubai mainland business with 100% foreign ownership. Fast DED trade license registration, initial approvals, and full PRO assistance by Anchor Point.', '2026-11-02 14:36:29');
INSERT INTO `services` (`id`, `category_id`, `title`, `slug`, `badge`, `short_desc`, `content`, `featured_image`, `price_starting_aed`, `timeline`, `deliverables_json`, `requirements_json`, `faq_json`, `sort_order`, `is_featured`, `is_active`, `seo_title`, `seo_desc`, `created_at`) VALUES (2, 1, 'UAE Free Zone Company Setup', 'freezone-company-setup', '0% Tax & 100% Repatriation', 'Incorporate your business in top UAE free zones (IFZA, Meydan, DMCC, DAFZA, RAKEZ) with zero import/export duties and flexible flexi-desk packages.', '<p>UAE Free Zones offer international entrepreneurs the ideal ecosystem for cross-border commerce, consulting, e-commerce, and technology ventures. Enjoy 100% repatriation of capital and profits, exemption from personal income taxes, and minimal corporate compliance requirements.</p><h3>Top Recommended Free Zones</h3><ul><li><strong>IFZA (Dubai Silicon Oasis):</strong> Highly cost-effective with co-working desks and fast digital setup.</li><li><strong>Meydan Free Zone:</strong> Prestigious location near Downtown Dubai with smart digital portal approvals.</li><li><strong>DMCC (JLT Dubai):</strong> Global hub for commodities, trade, crypto, and large corporate enterprises.</li><li><strong>DAFZA & RAKEZ:</strong> Excellent infrastructure for logistics, industrial manufacturing, and regional distribution.</li></ul><p>We analyze your business model to recommend the optimal free zone jurisdiction, maximizing cost efficiency and ensuring smooth corporate bank account opening.</p>', '/uploads/services/freezone-company-setup.jpg', 5750.0, '2–4 business days', '["Free Zone Trade License","Certificate of Incorporation","Share Certificates","Lease Agreement / Flexi-Desk Allocation","Free Zone Establishment Card"]', '["Color passport copy of each shareholder","Passport-size digital photo with white background","Brief description of proposed business activities"]', '[{"q":"Do I need physical office space in a Free Zone?","a":"No. Many UAE free zones provide flexi-desk or virtual co-working options that include visa eligibility without requiring physical lease commitments."}]', 2, 1, 1, 'Free Zone Business Setup in Dubai & UAE | Cost & Packages', 'Affordable UAE Free Zone company setup with 0% personal tax and 100% profit repatriation. Packages start from AED 5,750 with IFZA, Meydan, and DMCC.', '2026-11-02 14:36:29');
INSERT INTO `services` (`id`, `category_id`, `title`, `slug`, `badge`, `short_desc`, `content`, `featured_image`, `price_starting_aed`, `timeline`, `deliverables_json`, `requirements_json`, `faq_json`, `sort_order`, `is_featured`, `is_active`, `seo_title`, `seo_desc`, `created_at`) VALUES (3, 1, 'Trade License Renewal & Compliance', 'renewal-trade-license', 'Same-Day Express Renewal', 'Fast, hassle-free renewal of Dubai Mainland and Free Zone trade licenses, tenancy contracts (Ejari), and civil defense clearances without penalties.', '<p>Operating with an expired trade license can lead to heavy government fines, bank account freezing, and cancellation of employee visas. Anchor Point provides express trade license renewal services across Dubai and the Northern Emirates.</p><h3>What Our Renewal Service Covers</h3><ul><li>Reviewing existing license activity codes and removing obsolete requirements.</li><li>Ejari contract renewal and office tenancy coordination.</li><li>External department approvals (DM, RTA, SIRA, Civil Defence).</li><li>Immediate clearance of any pending ministry fines or blocks.</li></ul>', '/uploads/services/renewal-trade-license.jpg', 1500.0, '24–48 hours', '["Renewed DED / Free Zone Commercial License","Updated Chamber of Commerce Certificate","Renewed Ejari Registration Certificate"]', '["Copy of existing Trade License","Tenancy Contract and Ejari Certificate","Valid passports of partners/shareholders"]', '[{"q":"What is the grace period for trade license renewal in Dubai?","a":"Most Dubai authorities offer a 30-day grace period from the expiry date, after which monthly fines of AED 250 to AED 500 accumulate."}]', 3, 0, 1, 'Dubai Trade License Renewal Service | Avoid Fines Fast', 'Renew your Dubai trade license within 24 hours. Full Ejari coordination, fine clearing, and Chamber of Commerce renewal by Anchor Point.', '2026-11-02 14:36:29');
INSERT INTO `services` (`id`, `category_id`, `title`, `slug`, `badge`, `short_desc`, `content`, `featured_image`, `price_starting_aed`, `timeline`, `deliverables_json`, `requirements_json`, `faq_json`, `sort_order`, `is_featured`, `is_active`, `seo_title`, `seo_desc`, `created_at`) VALUES (4, 2, 'UAE Golden Visa & Investor Residency', 'golden-visa-services', '10-Year Renewable Residency', 'Secure the prestigious 10-year UAE Golden Visa for real estate investors, business owners, senior executives, and specialized talents with family sponsorship.', '<p>The UAE Golden Visa is a long-term residency program enabling foreign nationals to live, work, and study in the UAE without a national sponsor. Holders enjoy 100% self-sponsored residency, the ability to stay outside the UAE beyond 6 months without invalidation, and sponsorship of spouses, children, and domestic helpers.</p><h3>Eligible Categories</h3><ul><li><strong>Real Estate Investors:</strong> Property owners with investments worth AED 2 Million or more.</li><li><strong>Entrepreneurs & Business Owners:</strong> Shareholders of UAE enterprises with audited revenues.</li><li><strong>Executive Leaders & Professionals:</strong> High-salary professionals (AED 30,000+ monthly basic salary) with accredited degrees.</li><li><strong>Creative & Specialized Talents:</strong> Artists, researchers, software engineers, and innovators.</li></ul><p>Anchor Point guides you through pre-approval, nomination, document attestation, medical fitness, and Emirates ID biometric processing for your entire family.</p>', '/uploads/services/golden-visa-services.jpg', 4500.0, '5–7 business days', '["10-Year UAE Residency Visa E-Stamping","10-Year Gold Emirates ID Card","Family Sponsorship Clearances"]', '["Passport copy with 6+ months validity","Title Deed (for property investors) or employment contract + attested degree","6 months personal bank statement"]', '[{"q":"Can I sponsor my parents on a Golden Visa?","a":"Yes, Golden Visa holders can sponsor their parents for a renewable 10-year residency visa."}]', 11, 1, 1, 'UAE Golden Visa Services Dubai | 10-Year Investor Residency', 'Obtain your 10-year UAE Golden Visa smoothly. Full eligibility pre-check, property investor filing, executive approvals, and family sponsorship.', '2026-11-02 14:36:29');
INSERT INTO `services` (`id`, `category_id`, `title`, `slug`, `badge`, `short_desc`, `content`, `featured_image`, `price_starting_aed`, `timeline`, `deliverables_json`, `requirements_json`, `faq_json`, `sort_order`, `is_featured`, `is_active`, `seo_title`, `seo_desc`, `created_at`) VALUES (5, 4, 'Corporate Bank Account Opening Assistance', 'corporate-bank-account', 'Guaranteed Bank Introductions', 'Expert guidance to secure digital and tier-1 corporate bank accounts with leading UAE banks including Emirates NBD, Mashreq, WIO, and FAB.', '<p>Opening a corporate bank account in the UAE requires rigorous adherence to Know-Your-Customer (KYC) and Anti-Money Laundering (AML) standards. Many applicants face prolonged delays or rejections due to incomplete business profiles or misaligned documentation.</p><p>Anchor Point partners directly with leading UAE corporate banking officers to ensure your application is pre-screened, compliant, and approved expeditiously.</p><h3>Supported Financial Institutions</h3><ul><li><strong>WIO Bank:</strong> Modern, 100% digital business banking with fast approvals in 48 hours.</li><li><strong>Mashreq NeoBiz:</strong> Competitive fee structure tailored for SMEs and startups.</li><li><strong>Emirates NBD & Commercial Bank of Dubai (CBD):</strong> Tier-1 legacy banks with international trade finance and multi-currency facilities.</li><li><strong>First Abu Dhabi Bank (FAB) & ADCB:</strong> Robust institutional banking for large corporate groups.</li></ul>', '/uploads/services/corporate-bank-account.jpg', 2500.0, '5–10 business days', '["Complete Business Profile & KYC Dossier","Official Banker Introduction Meeting","Multi-Currency Corporate Account IBAN & Online Banking Setup"]', '["Valid UAE Trade License & MOA","Shareholders passport, visa, and Emirates ID","6 months personal bank statements of signatories","Corporate profile and business invoices/contracts"]', '[{"q":"Can a Free Zone company open a UAE corporate bank account?","a":"Yes, Free Zone companies can readily open corporate bank accounts with local and digital banks in the UAE subject to standard compliance checks."}]', 26, 1, 1, 'Corporate Bank Account Opening in Dubai UAE | Fast Approval', 'Open a corporate bank account in Dubai with Emirates NBD, Mashreq, Wio, or FAB. Expert KYC pre-screening and guaranteed banker introductions.', '2026-11-02 14:36:29');
INSERT INTO `services` (`id`, `category_id`, `title`, `slug`, `badge`, `short_desc`, `content`, `featured_image`, `price_starting_aed`, `timeline`, `deliverables_json`, `requirements_json`, `faq_json`, `sort_order`, `is_featured`, `is_active`, `seo_title`, `seo_desc`, `created_at`) VALUES (6, 3, 'Corporate P.R.O. & Government Liaison Services', 'pro-services', 'Comprehensive Ministry Support', 'Outsource all your government paperwork: GDRFA visas, MOHRE labour quotas, Tasheel contracts, Dubai Municipality approvals, and document attestations.', '<p>Navigating UAE government departments requires in-depth knowledge of evolving legal procedures and bilingual Arabic documentation. Anchor Point acts as your dedicated corporate Public Relations Officer, eliminating long queues and administrative delays.</p><h3>Our P.R.O. Services Include:</h3><ul><li>MOHRE Work Permit issuance, modifications, and quota increases.</li><li>GDRFA residence visa processing, transfers, and cancellations.</li><li>Emirates ID VIP biometric appointment booking and typing.</li><li>Ministry of Foreign Affairs (MOFA) degree and certificate attestations.</li><li>Dubai Customs client code registration and annual renewals.</li></ul>', '/uploads/services/pro-services.jpg', 800.0, '1–3 business days', '["Approved government transaction receipts","Stamped residency visas & electronic work permits","Certified MOFA attestations"]', '["Company trade license copy","Authorized signatory card / POA","Specific employee or applicant documents"]', '[{"q":"Can we hire Anchor Point on an annual PRO retainer?","a":"Yes, we provide flexible monthly and annual corporate PRO retainer packages tailored to small businesses and growing enterprises."}]', 13, 1, 1, 'Corporate PRO Services in Dubai | Government Document Clearing', 'Professional PRO services in Dubai. Hassle-free handling of GDRFA visas, MOHRE permits, Tasheel, Amer, and MOFA attestations for companies.', '2026-11-02 14:36:29');
INSERT INTO `services` (`id`, `category_id`, `title`, `slug`, `badge`, `short_desc`, `content`, `featured_image`, `price_starting_aed`, `timeline`, `deliverables_json`, `requirements_json`, `faq_json`, `sort_order`, `is_featured`, `is_active`, `seo_title`, `seo_desc`, `created_at`) VALUES (7, 3, 'Local Service Agent & Corporate Sponsorship', 'local-agent-service', '100% Operational Control', 'Reliable, corporate UAE national representation for civil companies and professional licenses with iron-clad side agreements protecting 100% of your earnings.', '<p>For specialized professional activities and branch offices of foreign entities that require an Emirati Local Service Agent (LSA), Anchor Point provides dependable, vetted corporate representation.</p><p>We ensure comprehensive legal agreements through Dubai Courts that safeguard your complete operational independence, intellectual property, and financial returns.</p>', '/uploads/services/local-agent-service.jpg', 3000.0, '2 business days', '["Court-Notarized Local Service Agent Agreement","Power of Attorney granting complete managerial authority","Updated Commercial Trade License"]', '["Existing Trade License or Initial Approval","Shareholder identification"]', '[{"q":"Does a Local Service Agent have shares in my business?","a":"No. A Local Service Agent has zero shares, zero operational control, and zero claim to company profits. They simply act as the liaison to local ministries."}]', 14, 0, 1, 'UAE Local Service Agent & Corporate Nominee | Dubai Legal Support', 'Secure a trusted Local Service Agent (LSA) in Dubai with 100% beneficial ownership protection and court-notarized investor protection contracts.', '2026-11-02 14:36:29');
INSERT INTO `services` (`id`, `category_id`, `title`, `slug`, `badge`, `short_desc`, `content`, `featured_image`, `price_starting_aed`, `timeline`, `deliverables_json`, `requirements_json`, `faq_json`, `sort_order`, `is_featured`, `is_active`, `seo_title`, `seo_desc`, `created_at`) VALUES (8, 1, 'Company Liquidation & License Cancellation', 'company-liquidation', 'Full Ministry Clearance', 'Officially close and de-register your Dubai Mainland or Free Zone business with full audit reports, tax clearances, and cancellation of government files.', '<p>Proper legal dissolution of a UAE entity is critical to avoid accumulating annual license fines, immigration blacklist records, and travel bans for partners and managers.</p><p>Anchor Point manages the full liquidation lifecycle: appointing an approved liquidator, publishing mandatory newspaper gazette notices, clearing MOHRE and GDRFA establishment cards, and obtaining final cancellation certificates from DED.</p>', '/uploads/services/company-liquidation.jpg', 3500.0, '15–30 business days', '["Official DED License Cancellation Certificate","Liquidator Final Audit Report","MOHRE & Immigration Establishment File Closure Proofs"]', '["Original trade license and commercial register","Company liquidation board resolution","VAT de-registration clearance from FTA"]', '[{"q":"Is a newspaper announcement mandatory for Dubai company liquidation?","a":"Yes, a 30-day (Mainland) or 14-day (Free Zone) public notice in two local daily newspapers is legally required to invite potential creditor claims."}]', 6, 0, 1, 'Dubai Company Liquidation & Trade License Cancellation', 'Close your UAE business legally without lingering liabilities. Full liquidator audit, newspaper notice, tax clearance, and DED de-registration.', '2026-11-02 14:36:29');
INSERT INTO `services` (`id`, `category_id`, `title`, `slug`, `badge`, `short_desc`, `content`, `featured_image`, `price_starting_aed`, `timeline`, `deliverables_json`, `requirements_json`, `faq_json`, `sort_order`, `is_featured`, `is_active`, `seo_title`, `seo_desc`, `created_at`) VALUES (9, 2, 'Emirates ID & Visa Medical Typing Services', 'emirates-id-typing', 'Fast-Track Typing Desk', 'Express government typing for Federal Authority for Identity (ICP) Emirates IDs, DHA Visa Medical Fitness exams, and biometric appointments.', '<p>Whether applying for a new residency visa or renewing an existing permit, swift processing of Emirates ID and Medical Fitness typing is essential. We offer error-free typing, appointment scheduling at VIP fitness centers, and doorstep Emirates ID delivery tracking.</p>', '/uploads/services/emirates-id-typing.jpg', 350.0, 'Same-Day Service', '["Official ICP Emirates ID Application Form","DHA / MOHAP Medical Fitness Typing Receipt","VIP Biometrics Appointment Confirmation"]', '["Original passport or copy","Entry visa permit or current residence visa page","Passport-size digital photograph"]', '[{"q":"Can I get 24-hour visa medical test results in Dubai?","a":"Yes, DHA VIP Medical Fitness centers provide express test results within 4 to 24 hours."}]', 12, 0, 1, 'Emirates ID & Visa Medical Typing Center Dubai | Express Booking', 'Same-day Emirates ID typing and DHA Visa Medical Fitness appointment bookings in Dubai. Zero queues and express delivery support.', '2026-11-02 14:36:29');
INSERT INTO `services` (`id`, `category_id`, `title`, `slug`, `badge`, `short_desc`, `content`, `featured_image`, `price_starting_aed`, `timeline`, `deliverables_json`, `requirements_json`, `faq_json`, `sort_order`, `is_featured`, `is_active`, `seo_title`, `seo_desc`, `created_at`) VALUES (10, 3, 'Dubai Police Good Conduct Clearance Certificate', 'police-clearance-certificate', 'Official CID Verification', 'Fast-track issuance and ministry attestation of Dubai Police Clearance Certificates for immigration, employment, and licensing.', '<p>A Certificate of Good Conduct issued by Dubai Police verifies that an individual has no criminal record in the UAE. It is frequently requested for foreign employment, international migration, and regulatory licensing.</p>', '/uploads/services/dubai-police-clearance.jpg', 450.0, '24 hours', '["Digitally verified Dubai Police Good Conduct Certificate with official QR code"]', '["Emirates ID copy or passport copy","Valid active email and mobile number"]', '[{"q":"Can expats who already left the UAE obtain a Dubai Police Clearance?","a":"Yes, previous UAE residents can obtain a certificate by providing fingerprint cards attested by the UAE Embassy in their home country."}]', 18, 0, 1, 'Dubai Police Clearance Certificate Service | Fast CID Certificate', 'Get your Dubai Police Good Conduct Certificate within 24 hours. Digital processing, MOFA attestation, and international delivery support.', '2026-11-02 14:36:29');
INSERT INTO `services` (`id`, `category_id`, `title`, `slug`, `badge`, `short_desc`, `content`, `featured_image`, `price_starting_aed`, `timeline`, `deliverables_json`, `requirements_json`, `faq_json`, `sort_order`, `is_featured`, `is_active`, `seo_title`, `seo_desc`, `created_at`) VALUES (11, 1, 'Company File Update & License Amendments', 'company-file-update', 'License & Contract Amendments', 'Update trade license activities, partners, manager, address or legal form with DET, free zones and MOHRE without interrupting operations.', '<p>Businesses evolve, and your license must evolve with them. We handle every amendment to your company file, from adding new activities to changing partners, so your license, contracts and government records always match.</p><h3>What Our Service Covers</h3><ul><li>Adding or removing business activities</li><li>Change of partners, manager or shareholding</li><li>Trade name and legal form changes</li><li>Office address and Ejari updates</li><li>MOHRE and immigration establishment file updates</li></ul><h3>How It Works</h3><ol><li><strong>Free consultation</strong> on WhatsApp or at our Al Jafiliya office.</li><li><strong>Document review</strong> and government submission by our PRO team.</li><li><strong>Tracking &amp; delivery</strong> — you receive approved documents with status updates.</li></ol>', '/uploads/services/company-file-update.jpg', 1200.0, '2–5 business days', '["Amended trade license","Updated MOA / addendum","Updated establishment card","Chamber of Commerce amendment certificate"]', '["Current trade license","Passports and Emirates IDs of partners","Signed partner resolution or amendment","Tenancy contract and Ejari (for address changes)"]', '[{"q":"Can I add a new activity to my existing trade license?","a":"Yes. Most activities can be added to an existing Mainland or Free Zone license after approval from the relevant authority. We confirm requirements and costs before you commit."}]', 4, 0, 1, 'Company File Update & Trade License Amendment Dubai', 'Update your Dubai trade license: add activities, change partners, manager or address. Fast DET, Free Zone and MOHRE amendments by Anchor Point.', '2026-11-02 15:38:16');
INSERT INTO `services` (`id`, `category_id`, `title`, `slug`, `badge`, `short_desc`, `content`, `featured_image`, `price_starting_aed`, `timeline`, `deliverables_json`, `requirements_json`, `faq_json`, `sort_order`, `is_featured`, `is_active`, `seo_title`, `seo_desc`, `created_at`) VALUES (12, 1, 'Modification of Visa Quota (MOHRE)', 'modification-of-quota', 'Increase Your Visa Capacity', 'Increase or modify your company labour and visa quota with MOHRE so you can hire and sponsor more employees.', '<p>Your visa quota decides how many employees your company can sponsor. When you outgrow it, we prepare the MOHRE application, office-space justification and approvals needed to raise it.</p><h3>What Our Service Covers</h3><ul><li>Quota assessment based on office size and activity</li><li>MOHRE establishment file review</li><li>Quota increase application and tracking</li><li>Immigration card update after approval</li></ul><h3>How It Works</h3><ol><li><strong>Free consultation</strong> on WhatsApp or at our Al Jafiliya office.</li><li><strong>Document review</strong> and government submission by our PRO team.</li><li><strong>Tracking &amp; delivery</strong> — you receive approved documents with status updates.</li></ol>', '/uploads/services/modification-of-quota.jpg', 900.0, '1–3 business days', '["MOHRE quota approval","Updated establishment card","Updated labour quota record"]', '["Valid trade license","Tenancy contract / Ejari showing office area","Authorised signatory passport and Emirates ID","Existing establishment card"]', '[{"q":"How many visas can my company sponsor?","a":"The quota depends on your license type, activity and the size of your registered office. We review these before applying so you know the realistic number up front."}]', 5, 0, 1, 'Visa Quota Modification Dubai | MOHRE Labour Quota Increase', 'Need more employee visas? Anchor Point handles MOHRE visa quota modification and increases for Dubai Mainland and Free Zone companies.', '2026-11-02 15:38:16');
INSERT INTO `services` (`id`, `category_id`, `title`, `slug`, `badge`, `short_desc`, `content`, `featured_image`, `price_starting_aed`, `timeline`, `deliverables_json`, `requirements_json`, `faq_json`, `sort_order`, `is_featured`, `is_active`, `seo_title`, `seo_desc`, `created_at`) VALUES (13, 2, 'Investor & Partner Residence Visa', 'investor-partner-visa', 'Residency for Owners & Partners', 'Residence visas for company investors, shareholders and partners, including medical, Emirates ID and visa stamping.', '<p>As a shareholder or partner in a UAE company you can sponsor your own residence visa. We manage the entry permit, status change, medical test, Emirates ID biometrics and visa stamping in one coordinated process.</p><h3>What Our Service Covers</h3><ul><li>Entry permit or status change inside the UAE</li><li>Medical fitness test booking</li><li>Emirates ID application and biometrics</li><li>Residence visa stamping</li></ul><h3>How It Works</h3><ol><li><strong>Free consultation</strong> on WhatsApp or at our Al Jafiliya office.</li><li><strong>Document review</strong> and government submission by our PRO team.</li><li><strong>Tracking &amp; delivery</strong> — you receive approved documents with status updates.</li></ol>', '/uploads/services/investor-partner-visa.jpg', 3200.0, '5–7 business days', '["UAE residence visa","Emirates ID","Medical fitness certificate"]', '["Passport copy with 6+ months validity","Passport-size photo with white background","Valid trade license and MOA / partnership proof","Establishment card"]', '[{"q":"How long is an investor visa valid?","a":"Investor and partner visas are generally issued for 2 years and are renewable. Your trade license and establishment card must stay valid."}]', 7, 1, 1, 'Investor & Partner Visa Dubai | UAE Residence for Business Owners', 'Get your UAE investor or partner residence visa with medical, Emirates ID and stamping handled end to end by Anchor Point.', '2026-11-02 15:38:16');
INSERT INTO `services` (`id`, `category_id`, `title`, `slug`, `badge`, `short_desc`, `content`, `featured_image`, `price_starting_aed`, `timeline`, `deliverables_json`, `requirements_json`, `faq_json`, `sort_order`, `is_featured`, `is_active`, `seo_title`, `seo_desc`, `created_at`) VALUES (14, 2, 'Employment Visa & Labour Contract', 'employment-visa', 'New Hire & Visa Transfer', 'Hire overseas or inside-UAE employees with work permit, labour contract, medical, Emirates ID and visa stamping handled for you.', '<p>From the MOHRE offer letter and work permit to the visa stamp, we manage every government step for your new employees, whether they are arriving from abroad or transferring from another sponsor.</p><h3>What Our Service Covers</h3><ul><li>MOHRE offer letter and work permit</li><li>Entry permit and status change</li><li>Medical test and Emirates ID biometrics</li><li>Labour contract registration via Tasheel</li></ul><h3>How It Works</h3><ol><li><strong>Free consultation</strong> on WhatsApp or at our Al Jafiliya office.</li><li><strong>Document review</strong> and government submission by our PRO team.</li><li><strong>Tracking &amp; delivery</strong> — you receive approved documents with status updates.</li></ol>', '/uploads/services/employment-visa.jpg', 2800.0, '5–7 business days', '["Residence visa","Emirates ID","Approved labour contract"]', '["Employee passport copy and photo","Educational certificates (attested where required)","Company trade license and establishment card","Signed employment offer"]', '[{"q":"Can you transfer an employee from another company?","a":"Yes. We handle visa transfers including the new labour contract, cancellation clearance and Emirates ID update."}]', 8, 0, 1, 'Employment Visa Dubai | Work Permit & Labour Contract Services', 'Hire staff in the UAE with ease. Anchor Point processes employment visas, MOHRE work permits and labour contracts for companies in Dubai.', '2026-11-02 15:38:16');
INSERT INTO `services` (`id`, `category_id`, `title`, `slug`, `badge`, `short_desc`, `content`, `featured_image`, `price_starting_aed`, `timeline`, `deliverables_json`, `requirements_json`, `faq_json`, `sort_order`, `is_featured`, `is_active`, `seo_title`, `seo_desc`, `created_at`) VALUES (15, 2, 'Family Sponsorship Visa', 'family-visa', 'Spouse, Children & Parents', 'Sponsor your spouse, children or parents on a UAE residence visa with all attestations, medicals and Emirates IDs.', '<p>Bring your family to live with you in the UAE. We check your sponsorship eligibility, prepare attested documents and manage the visa, medical and Emirates ID steps for each family member.</p><h3>What Our Service Covers</h3><ul><li>Eligibility check (salary / contract / accommodation)</li><li>Marriage and birth certificate attestation guidance</li><li>Entry permit, medical and biometrics</li><li>Residence visa stamping and Emirates ID</li></ul><h3>How It Works</h3><ol><li><strong>Free consultation</strong> on WhatsApp or at our Al Jafiliya office.</li><li><strong>Document review</strong> and government submission by our PRO team.</li><li><strong>Tracking &amp; delivery</strong> — you receive approved documents with status updates.</li></ol>', '/uploads/services/family-visa.jpg', 2400.0, '5–7 business days', '["Family residence visas","Emirates IDs","Medical fitness certificates"]', '["Sponsor passport, visa and Emirates ID","Attested marriage / birth certificates","Tenancy contract / Ejari","Salary certificate or labour contract"]', '[{"q":"What salary is required to sponsor my family?","a":"Requirements depend on your profession and the authorities at the time of application. Share your details on WhatsApp and we will confirm eligibility before any fees."}]', 9, 0, 1, 'Family Visa Dubai | Spouse, Children & Parents Sponsorship', 'Sponsor your family in the UAE. Anchor Point handles attestations, medicals, Emirates ID and residence visas for spouse, children and parents.', '2026-11-02 15:38:16');
INSERT INTO `services` (`id`, `category_id`, `title`, `slug`, `badge`, `short_desc`, `content`, `featured_image`, `price_starting_aed`, `timeline`, `deliverables_json`, `requirements_json`, `faq_json`, `sort_order`, `is_featured`, `is_active`, `seo_title`, `seo_desc`, `created_at`) VALUES (16, 2, 'Freelance Visa & Permit', 'freelance-visa', 'Work for Yourself in the UAE', 'Obtain a freelance permit and UAE residence visa without needing a full company license or an employer sponsor.', '<p>Freelance permits let creatives, consultants and IT professionals live and work legally in the UAE. We choose the right free-zone package for your activity and manage the permit, visa and Emirates ID.</p><h3>What Our Service Covers</h3><ul><li>Free-zone freelance package selection</li><li>Permit application and approval</li><li>Residence visa and medical</li><li>Emirates ID and bank-account guidance</li></ul><h3>How It Works</h3><ol><li><strong>Free consultation</strong> on WhatsApp or at our Al Jafiliya office.</li><li><strong>Document review</strong> and government submission by our PRO team.</li><li><strong>Tracking &amp; delivery</strong> — you receive approved documents with status updates.</li></ol>', '/uploads/services/freelance-visa.jpg', 7500.0, '5–10 business days', '["Freelance permit","UAE residence visa","Emirates ID"]', '["Passport copy and photo","CV / portfolio and qualifications","Brief description of your freelance activity"]', '[{"q":"Can I sponsor my family on a freelance visa?","a":"In most cases yes, once you hold a valid residence visa and meet the income and housing requirements. We will confirm for your package."}]', 10, 0, 1, 'Freelance Visa Dubai | UAE Freelancer Permit & Residency', 'Get a UAE freelance permit and residence visa. Anchor Point guides freelancers, consultants and creatives through the full process.', '2026-11-02 15:38:16');
INSERT INTO `services` (`id`, `category_id`, `title`, `slug`, `badge`, `short_desc`, `content`, `featured_image`, `price_starting_aed`, `timeline`, `deliverables_json`, `requirements_json`, `faq_json`, `sort_order`, `is_featured`, `is_active`, `seo_title`, `seo_desc`, `created_at`) VALUES (17, 3, 'Dubai Municipality (DM) Trade Licensing Approval', 'dm-trade-licensing', 'Food, Health & Safety Approvals', 'Secure Dubai Municipality approvals for food, health and safety compliant business activities and premises.', '<p>Many activities, from restaurants and cafeterias to trading and cleaning, need Dubai Municipality approval before the license can be issued. We prepare drawings, documents and inspection bookings so approval goes through first time.</p><h3>What Our Service Covers</h3><ul><li>Initial approval and activity review</li><li>Premises plan and layout submission</li><li>Inspection booking and follow-up</li><li>Final DM approval for trade license</li></ul><h3>How It Works</h3><ol><li><strong>Free consultation</strong> on WhatsApp or at our Al Jafiliya office.</li><li><strong>Document review</strong> and government submission by our PRO team.</li><li><strong>Tracking &amp; delivery</strong> — you receive approved documents with status updates.</li></ol>', '/uploads/services/dm-trade-licensing.jpg', 800.0, '3–7 business days', '["DM approval certificate","Updated trade license activities"]', '["Trade license or initial approval","Tenancy contract / Ejari","Premises plan or layout","Authorised signatory ID"]', '[{"q":"Which activities need Dubai Municipality approval?","a":"Food and beverage, health, cleaning, general trading with storage and many other activities. We check your activity codes and confirm if DM approval is required."}]', 15, 0, 1, 'Dubai Municipality Trade License Approval | DM Approvals Dubai', 'Fast Dubai Municipality (DM) approvals for trade licensing, food and health activities handled by Anchor Point PRO specialists.', '2026-11-02 15:38:16');
INSERT INTO `services` (`id`, `category_id`, `title`, `slug`, `badge`, `short_desc`, `content`, `featured_image`, `price_starting_aed`, `timeline`, `deliverables_json`, `requirements_json`, `faq_json`, `sort_order`, `is_featured`, `is_active`, `seo_title`, `seo_desc`, `created_at`) VALUES (18, 3, 'RTA Trade Licensing Approval', 'rta-trade-licensing', 'Transport & Commercial Vehicle Approvals', 'Obtain Roads & Transport Authority approvals for transport, limousine, cargo and vehicle-related trade licenses.', '<p>Transport and vehicle-related businesses need RTA approval before trading. We prepare the application, NOC and vehicle documentation and track it until approval.</p><h3>What Our Service Covers</h3><ul><li>RTA initial approval and NOC</li><li>Commercial transport activity registration</li><li>Vehicle and driver documentation</li><li>Follow-up until approval is issued</li></ul><h3>How It Works</h3><ol><li><strong>Free consultation</strong> on WhatsApp or at our Al Jafiliya office.</li><li><strong>Document review</strong> and government submission by our PRO team.</li><li><strong>Tracking &amp; delivery</strong> — you receive approved documents with status updates.</li></ol>', '/uploads/services/rta-trade-licensing.jpg', 1000.0, '5–10 business days', '["RTA approval / NOC","Updated trade license"]', '["Trade license or initial approval","Tenancy contract / Ejari","Vehicle details and ownership documents","Authorised signatory ID"]', '[{"q":"Which businesses need RTA approval?","a":"Transport, limousine and taxi services, cargo and logistics, vehicle rental and some vehicle trading activities."}]', 16, 0, 1, 'RTA Trade License Approval Dubai | Transport Activity NOC', 'Get Roads & Transport Authority (RTA) approvals for your Dubai transport or vehicle business with Anchor Point.', '2026-11-02 15:38:16');
INSERT INTO `services` (`id`, `category_id`, `title`, `slug`, `badge`, `short_desc`, `content`, `featured_image`, `price_starting_aed`, `timeline`, `deliverables_json`, `requirements_json`, `faq_json`, `sort_order`, `is_featured`, `is_active`, `seo_title`, `seo_desc`, `created_at`) VALUES (19, 3, 'SIRA Trade Licensing Approval (Security)', 'sira-trade-licensing', 'Security Industry Regulatory Agency', 'Secure Security Industry Regulatory Agency (SIRA) approval for security, CCTV and guarding activities in Dubai.', '<p>Security guarding, CCTV installation and related activities are regulated by SIRA in Dubai. We manage the application, staff clearances and compliance documentation needed for approval.</p><h3>What Our Service Covers</h3><ul><li>SIRA initial approval application</li><li>Activity and premises compliance check</li><li>Staff and manager clearance guidance</li><li>Final approval for trade license</li></ul><h3>How It Works</h3><ol><li><strong>Free consultation</strong> on WhatsApp or at our Al Jafiliya office.</li><li><strong>Document review</strong> and government submission by our PRO team.</li><li><strong>Tracking &amp; delivery</strong> — you receive approved documents with status updates.</li></ol>', '/uploads/services/sera-trade-licensing.jpg', 1500.0, '5–10 business days', '["SIRA approval certificate","Updated trade license"]', '["Trade license or initial approval","Tenancy contract / Ejari","Manager and staff documents","Authorised signatory ID"]', '[{"q":"Do CCTV installation companies need SIRA approval?","a":"Yes. In Dubai, security systems and guarding activities require SIRA approval. We confirm the exact requirements for your activity."}]', 17, 0, 1, 'SIRA Approval Dubai | Security Company Trade License', 'Fast SIRA (Security Industry Regulatory Agency) approvals for security, CCTV and guarding trade licenses in Dubai.', '2026-11-02 15:38:16');
INSERT INTO `services` (`id`, `category_id`, `title`, `slug`, `badge`, `short_desc`, `content`, `featured_image`, `price_starting_aed`, `timeline`, `deliverables_json`, `requirements_json`, `faq_json`, `sort_order`, `is_featured`, `is_active`, `seo_title`, `seo_desc`, `created_at`) VALUES (20, 3, 'Dubai Police Lost Item Certificate', 'dubai-police-lost-item', 'Official Lost Report', 'Report lost documents or items and receive an official Dubai Police lost-item certificate for replacement of IDs and passports.', '<p>Lost your passport, Emirates ID, license or important documents? We file the report with Dubai Police and deliver the official certificate you need to start replacements.</p><h3>What Our Service Covers</h3><ul><li>Online lost-item report filing</li><li>Official certificate with QR verification</li><li>Guidance for passport / Emirates ID replacement</li></ul><h3>How It Works</h3><ol><li><strong>Free consultation</strong> on WhatsApp or at our Al Jafiliya office.</li><li><strong>Document review</strong> and government submission by our PRO team.</li><li><strong>Tracking &amp; delivery</strong> — you receive approved documents with status updates.</li></ol>', '/uploads/services/dubai-police-loss-item.jpg', 150.0, 'Same day', '["Dubai Police lost-item certificate"]', '["Emirates ID or passport copy (if available)","Valid mobile number and email","Description of the lost item"]', '[{"q":"How fast can I get the certificate?","a":"In most cases the same day, once details are verified."}]', 19, 0, 1, 'Dubai Police Lost Item Certificate | Lost Passport & ID Report', 'Get an official Dubai Police lost-item certificate fast. Anchor Point files the report and guides your document replacement.', '2026-11-02 15:38:16');
INSERT INTO `services` (`id`, `category_id`, `title`, `slug`, `badge`, `short_desc`, `content`, `featured_image`, `price_starting_aed`, `timeline`, `deliverables_json`, `requirements_json`, `faq_json`, `sort_order`, `is_featured`, `is_active`, `seo_title`, `seo_desc`, `created_at`) VALUES (21, 3, 'Power of Attorney (POA) Drafting & Attestation', 'power-of-attorney', 'Notarised & Court-Attested', 'Draft, notarise and attest a Power of Attorney for business, property, vehicle or banking matters in the UAE.', '<p>A Power of Attorney lets someone you trust act on your behalf. We prepare the Arabic-English draft, arrange notarisation and handle attestation so your POA is accepted by banks, courts and authorities.</p><h3>What Our Service Covers</h3><ul><li>Bilingual POA drafting</li><li>Notary public / court registration</li><li>MOFA attestation when needed</li><li>Guidance on scope and validity</li></ul><h3>How It Works</h3><ol><li><strong>Free consultation</strong> on WhatsApp or at our Al Jafiliya office.</li><li><strong>Document review</strong> and government submission by our PRO team.</li><li><strong>Tracking &amp; delivery</strong> — you receive approved documents with status updates.</li></ol>', '/uploads/services/power-of-attorney.jpg', 600.0, '1–2 business days', '["Notarised Power of Attorney","Attestation stamps where required"]', '["Passport / Emirates ID of the principal","Passport / ID of the attorney","Clear description of powers to be granted"]', '[{"q":"Can I give a POA from outside the UAE?","a":"Yes, but it must be signed and attested in the country of issue and then legalised for UAE use. We guide you through the steps."}]', 20, 0, 1, 'Power of Attorney Dubai | POA Drafting, Notary & Attestation', 'Professional POA drafting, notarisation and attestation in Dubai for business, property, vehicle and banking matters.', '2026-11-02 15:38:16');
INSERT INTO `services` (`id`, `category_id`, `title`, `slug`, `badge`, `short_desc`, `content`, `featured_image`, `price_starting_aed`, `timeline`, `deliverables_json`, `requirements_json`, `faq_json`, `sort_order`, `is_featured`, `is_active`, `seo_title`, `seo_desc`, `created_at`) VALUES (22, 3, 'Establishment Card (Immigration & Labour File)', 'establishment-card', 'Open Your Company Visa File', 'Issue or renew your company establishment card and open the immigration and labour file required to sponsor employees.', '<p>The establishment card links your company to the immigration and labour authorities and is required before you can sponsor any visa. We open, renew or amend it quickly and correctly.</p><h3>What Our Service Covers</h3><ul><li>New establishment card issuance</li><li>Card renewal and amendment</li><li>Linking quota and e-signature card</li><li>Immigration file clearance</li></ul><h3>How It Works</h3><ol><li><strong>Free consultation</strong> on WhatsApp or at our Al Jafiliya office.</li><li><strong>Document review</strong> and government submission by our PRO team.</li><li><strong>Tracking &amp; delivery</strong> — you receive approved documents with status updates.</li></ol>', '/uploads/services/establishment-card.jpg', 1100.0, '2–4 business days', '["Establishment card","Labour and immigration file number"]', '["Valid trade license","Tenancy contract / Ejari","Passport and Emirates ID of owner / manager","MOA or partnership agreement"]', '[{"q":"When do I need an establishment card?","a":"Immediately after trade license issuance if you plan to sponsor any employee or partner visa. It must also be renewed each year."}]', 21, 0, 1, 'Establishment Card Dubai | Immigration & Labour File Services', 'Issue or renew your company establishment card in Dubai quickly. Anchor Point manages immigration and labour file services.', '2026-11-02 15:38:16');
INSERT INTO `services` (`id`, `category_id`, `title`, `slug`, `badge`, `short_desc`, `content`, `featured_image`, `price_starting_aed`, `timeline`, `deliverables_json`, `requirements_json`, `faq_json`, `sort_order`, `is_featured`, `is_active`, `seo_title`, `seo_desc`, `created_at`) VALUES (23, 5, 'UAE Driving License Renewal (RTA)', 'driving-license-renewal', 'Renew in Minutes', 'Renew your UAE driving license with eye test and RTA processing handled by our team, with no queues.', '<p>Do not risk fines for an expired license. We arrange the eye test, submit your renewal to RTA and deliver the renewed license so you can keep driving without interruption.</p><h3>What Our Service Covers</h3><ul><li>Eye test booking</li><li>RTA renewal submission</li><li>Traffic fine clearance check</li><li>License delivery</li></ul><h3>How It Works</h3><ol><li><strong>Free consultation</strong> on WhatsApp or at our Al Jafiliya office.</li><li><strong>Document review</strong> and government submission by our PRO team.</li><li><strong>Tracking &amp; delivery</strong> — you receive approved documents with status updates.</li></ol>', '/uploads/services/driving-license-renewal.jpg', 250.0, 'Same day', '["Renewed driving license"]', '["Current driving license","Emirates ID","Valid mobile number"]', '[{"q":"Can I renew my license if I have unpaid fines?","a":"Outstanding fines usually must be cleared first. We can check and settle them as part of the service."}]', 22, 1, 1, 'Driving License Renewal Dubai | RTA License Renewal Service', 'Renew your UAE driving license the easy way. Anchor Point handles the eye test and RTA renewal with delivery to you.', '2026-11-02 15:38:16');
INSERT INTO `services` (`id`, `category_id`, `title`, `slug`, `badge`, `short_desc`, `content`, `featured_image`, `price_starting_aed`, `timeline`, `deliverables_json`, `requirements_json`, `faq_json`, `sort_order`, `is_featured`, `is_active`, `seo_title`, `seo_desc`, `created_at`) VALUES (24, 5, 'Dubai Salik Registration & Tag Activation', 'dubai-salik', 'Toll Account Setup', 'Register a Salik toll account, activate your tag and top up your balance so you never get a toll fine.', '<p>Driving on Dubai roads requires an active Salik account. We register your vehicle, activate the tag and set up automatic top-up so toll gates charge your account correctly.</p><h3>What Our Service Covers</h3><ul><li>Salik account registration</li><li>Tag activation and installation guidance</li><li>Balance top-up and auto-recharge setup</li><li>Fine and balance check</li></ul><h3>How It Works</h3><ol><li><strong>Free consultation</strong> on WhatsApp or at our Al Jafiliya office.</li><li><strong>Document review</strong> and government submission by our PRO team.</li><li><strong>Tracking &amp; delivery</strong> — you receive approved documents with status updates.</li></ol>', '/uploads/services/dubai-salik.jpg', 120.0, 'Same day', '["Active Salik account and tag"]', '["Vehicle registration card (Mulkiya)","Emirates ID","Valid mobile number and email"]', '[{"q":"What happens if I drive through a Salik gate without a tag?","a":"A fine is applied for each crossing. Registering and keeping a balance avoids this."}]', 23, 0, 1, 'Dubai Salik Registration | Salik Tag Activation & Top-Up', 'Register your Dubai Salik account and activate your tag with Anchor Point. Fast, simple toll account setup.', '2026-11-02 15:38:16');
INSERT INTO `services` (`id`, `category_id`, `title`, `slug`, `badge`, `short_desc`, `content`, `featured_image`, `price_starting_aed`, `timeline`, `deliverables_json`, `requirements_json`, `faq_json`, `sort_order`, `is_featured`, `is_active`, `seo_title`, `seo_desc`, `created_at`) VALUES (25, 5, 'Abu Dhabi Darb Toll Registration', 'abu-dhabi-salik', 'Darb Account & Tag', 'Register your vehicle for the Abu Dhabi Darb toll system and manage your account and balance.', '<p>Abu Dhabi uses the Darb toll system on selected roads. We help register your vehicle, link your account and keep your balance topped up.</p><h3>What Our Service Covers</h3><ul><li>Darb account registration</li><li>Vehicle linking</li><li>Balance top-up guidance</li><li>Toll fine enquiry</li></ul><h3>How It Works</h3><ol><li><strong>Free consultation</strong> on WhatsApp or at our Al Jafiliya office.</li><li><strong>Document review</strong> and government submission by our PRO team.</li><li><strong>Tracking &amp; delivery</strong> — you receive approved documents with status updates.</li></ol>', '/uploads/services/abu-dhabi-salik.jpg', 120.0, 'Same day', '["Active Darb account"]', '["Vehicle registration card (Mulkiya)","Emirates ID","Valid mobile number and email"]', '[{"q":"Is Darb different from Dubai Salik?","a":"Yes. Darb is the Abu Dhabi toll system and Salik is the Dubai toll system. Each requires its own account."}]', 24, 0, 1, 'Abu Dhabi Darb Toll Registration | Account & Top-Up Help', 'Register for Abu Dhabi Darb tolls with Anchor Point. Account setup and balance help for UAE drivers.', '2026-11-02 15:38:16');
INSERT INTO `services` (`id`, `category_id`, `title`, `slug`, `badge`, `short_desc`, `content`, `featured_image`, `price_starting_aed`, `timeline`, `deliverables_json`, `requirements_json`, `faq_json`, `sort_order`, `is_featured`, `is_active`, `seo_title`, `seo_desc`, `created_at`) VALUES (26, 5, 'Vehicle Insurance & Registration (Mulkiya)', 'vehicle-insurance-registration', 'Comprehensive & Third-Party Cover', 'Compare and buy UAE vehicle insurance and renew your registration card (Mulkiya) with testing centre handling.', '<p>Renewing your car registration requires valid insurance and a technical test. We compare insurers, arrange the policy and complete the registration renewal so you receive your new Mulkiya.</p><h3>What Our Service Covers</h3><ul><li>Insurance quotation and comparison</li><li>Technical test booking</li><li>Registration renewal submission</li><li>Delivery of new Mulkiya</li></ul><h3>How It Works</h3><ol><li><strong>Free consultation</strong> on WhatsApp or at our Al Jafiliya office.</li><li><strong>Document review</strong> and government submission by our PRO team.</li><li><strong>Tracking &amp; delivery</strong> — you receive approved documents with status updates.</li></ol>', '/uploads/services/vehicle-insurance.jpg', 800.0, 'Same day', '["Insurance policy","Renewed vehicle registration (Mulkiya)"]', '["Current Mulkiya","Driving license / Emirates ID","Previous insurance details"]', '[{"q":"What is the price of car insurance in the UAE?","a":"Premiums depend on car value, age and driver history. The starting price shown is a service fee; we send you insurer quotations before you decide."}]', 25, 0, 1, 'Vehicle Insurance & Mulkiya Renewal Dubai | Car Registration', 'Buy UAE car insurance and renew your Mulkiya with Anchor Point. Quick comparison, testing and registration service.', '2026-11-02 15:38:16');
INSERT INTO `services` (`id`, `category_id`, `title`, `slug`, `badge`, `short_desc`, `content`, `featured_image`, `price_starting_aed`, `timeline`, `deliverables_json`, `requirements_json`, `faq_json`, `sort_order`, `is_featured`, `is_active`, `seo_title`, `seo_desc`, `created_at`) VALUES (27, 4, 'VAT & Corporate Tax Registration', 'vat-tax-registration', 'FTA Compliance Support', 'Register for UAE VAT and Corporate Tax with the Federal Tax Authority and stay compliant with filing deadlines.', '<p>UAE businesses above the mandatory thresholds must register for VAT and Corporate Tax. We handle FTA registration, TRN issuance and ongoing filing support so you avoid penalties.</p><h3>What Our Service Covers</h3><ul><li>VAT registration and TRN certificate</li><li>Corporate Tax registration</li><li>Return filing guidance and reminders</li><li>De-registration when required</li></ul><h3>How It Works</h3><ol><li><strong>Free consultation</strong> on WhatsApp or at our Al Jafiliya office.</li><li><strong>Document review</strong> and government submission by our PRO team.</li><li><strong>Tracking &amp; delivery</strong> — you receive approved documents with status updates.</li></ol>', '/uploads/services/vat-tax-registration.jpg', 1500.0, '3–7 business days', '["VAT certificate / TRN","Corporate Tax registration number"]', '["Trade license and MOA","Passport and Emirates ID of owner","Financial statements / turnover details","Bank account details"]', '[{"q":"When must I register for VAT?","a":"Mandatory VAT registration applies when taxable supplies exceed AED 375,000 in 12 months; voluntary registration is possible above AED 187,500."}]', 27, 1, 1, 'VAT & Corporate Tax Registration UAE | FTA Compliance Dubai', 'Register for UAE VAT and Corporate Tax with Anchor Point. FTA registration and filing support for Dubai businesses.', '2026-11-02 15:38:16');
INSERT INTO `services` (`id`, `category_id`, `title`, `slug`, `badge`, `short_desc`, `content`, `featured_image`, `price_starting_aed`, `timeline`, `deliverables_json`, `requirements_json`, `faq_json`, `sort_order`, `is_featured`, `is_active`, `seo_title`, `seo_desc`, `created_at`) VALUES (28, 4, 'Corporate Legal Support & Contract Advisory', 'corporate-legal-support', 'Contracts, MOAs & Disputes', 'Draft and review commercial contracts, MOAs, agreements and get legal guidance for your UAE business.', '<p>Strong contracts protect your business. We coordinate with licensed UAE legal advisers to draft and review agreements, shareholder arrangements and commercial documents.</p><h3>What Our Service Covers</h3><ul><li>Contract drafting and review</li><li>MOA and shareholder agreements</li><li>Commercial dispute guidance</li><li>Legal translation and notarisation</li></ul><h3>How It Works</h3><ol><li><strong>Free consultation</strong> on WhatsApp or at our Al Jafiliya office.</li><li><strong>Document review</strong> and government submission by our PRO team.</li><li><strong>Tracking &amp; delivery</strong> — you receive approved documents with status updates.</li></ol>', '/uploads/services/corporate-legal-support.jpg', 1500.0, 'Custom timeline', '["Drafted / reviewed legal documents","Legal advisory notes"]', '["Details of the parties","Draft or existing agreements","Summary of the matter or requirements"]', '[{"q":"Do you provide courtroom representation?","a":"We coordinate with licensed legal partners for court and arbitration matters when needed."}]', 28, 0, 1, 'Corporate Legal Support Dubai | Contract Drafting & Advisory', 'Corporate legal support in Dubai: contract drafting, MOAs, shareholder agreements and advisory with Anchor Point partners.', '2026-11-02 15:38:16');
INSERT INTO `services` (`id`, `category_id`, `title`, `slug`, `badge`, `short_desc`, `content`, `featured_image`, `price_starting_aed`, `timeline`, `deliverables_json`, `requirements_json`, `faq_json`, `sort_order`, `is_featured`, `is_active`, `seo_title`, `seo_desc`, `created_at`) VALUES (29, 4, 'Will Preparation & Registration (DIFC / Dubai Courts)', 'will-preparation', 'Protect Your Family & Assets', 'Prepare and register a UAE will for expats to protect your family and assets under your own wishes.', '<p>Expats living in the UAE can register a will so assets are distributed as they wish. We guide you through drafting and registration with the DIFC Wills Service or Dubai Courts.</p><h3>What Our Service Covers</h3><ul><li>Will drafting guidance</li><li>Guardianship and asset instructions</li><li>Registration with DIFC / Dubai Courts</li><li>Certified copies</li></ul><h3>How It Works</h3><ol><li><strong>Free consultation</strong> on WhatsApp or at our Al Jafiliya office.</li><li><strong>Document review</strong> and government submission by our PRO team.</li><li><strong>Tracking &amp; delivery</strong> — you receive approved documents with status updates.</li></ol>', '/uploads/services/will-preparation.jpg', 2500.0, '3–7 business days', '["Registered will","Certified copies"]', '["Passport and Emirates ID","List of assets and beneficiaries","Guardian details for minor children"]', '[{"q":"Is a will recognised for non-Muslim expats?","a":"Yes, a registered will lets non-Muslim expats choose how their UAE assets are distributed, subject to registration rules."}]', 29, 0, 1, 'Will Registration Dubai | DIFC Wills & Dubai Courts for Expats', 'Prepare and register a UAE will in Dubai. Anchor Point guides expats through DIFC and Dubai Courts will registration.', '2026-11-02 15:38:16');
INSERT INTO `services` (`id`, `category_id`, `title`, `slug`, `badge`, `short_desc`, `content`, `featured_image`, `price_starting_aed`, `timeline`, `deliverables_json`, `requirements_json`, `faq_json`, `sort_order`, `is_featured`, `is_active`, `seo_title`, `seo_desc`, `created_at`) VALUES (30, 4, 'Business Email & Domain Setup', 'business-email-setup', 'Professional @yourcompany.ae', 'Register your domain and set up professional business email with secure cloud workspace for your team.', '<p>A professional email address builds trust with clients and banks. We register your domain and configure secure business email, spam protection and mobile access for your team.</p><h3>What Our Service Covers</h3><ul><li>Domain registration (.ae, .com)</li><li>Business email accounts and aliases</li><li>SPF, DKIM and spam protection</li><li>Phone and Outlook configuration</li></ul><h3>How It Works</h3><ol><li><strong>Free consultation</strong> on WhatsApp or at our Al Jafiliya office.</li><li><strong>Document review</strong> and government submission by our PRO team.</li><li><strong>Tracking &amp; delivery</strong> — you receive approved documents with status updates.</li></ol>', '/uploads/services/business-email-setup.jpg', 350.0, 'Same day', '["Registered domain","Configured business email accounts"]', '["Company name and preferred domain","List of required email users","Trade license copy for .ae domains"]', '[{"q":"Can I use my own domain for business email?","a":"Yes. We can connect any domain you own or register a new one for you."}]', 30, 0, 1, 'Business Email Setup UAE | Domain & Professional Email', 'Set up professional business email and your domain in the UAE with Anchor Point. Fast, secure and fully configured.', '2026-11-02 15:38:16');
INSERT INTO `services` (`id`, `category_id`, `title`, `slug`, `badge`, `short_desc`, `content`, `featured_image`, `price_starting_aed`, `timeline`, `deliverables_json`, `requirements_json`, `faq_json`, `sort_order`, `is_featured`, `is_active`, `seo_title`, `seo_desc`, `created_at`) VALUES (31, 4, 'Corporate Website Development & Design', 'website-development', 'UI/UX + SEO-Ready', 'A fast, responsive and SEO-ready corporate website that presents your Dubai business professionally.', '<p>Your website is your digital office. We design and build modern, mobile-friendly websites with on-page SEO, contact forms and WhatsApp integration so clients can reach you instantly.</p><h3>What Our Service Covers</h3><ul><li>Custom responsive design</li><li>On-page SEO and fast loading</li><li>Contact and WhatsApp integration</li><li>Hosting and domain setup assistance</li></ul><h3>How It Works</h3><ol><li><strong>Free consultation</strong> on WhatsApp or at our Al Jafiliya office.</li><li><strong>Document review</strong> and government submission by our PRO team.</li><li><strong>Tracking &amp; delivery</strong> — you receive approved documents with status updates.</li></ol>', '/uploads/services/website-development.jpg', 2500.0, '7–14 business days', '["Live corporate website","Admin access and handover guide"]', '["Logo and brand colours","Company profile and services text","Photos or preferred references"]', '[{"q":"Can I edit the website myself later?","a":"Yes. We deliver an easy-to-use admin area or train your team so you can update content without developers."}]', 31, 0, 1, 'Website Development Dubai | Corporate Website Design & SEO', 'Corporate website design and development in Dubai. Responsive, SEO-ready websites built by Anchor Point.', '2026-11-02 15:38:16');

